'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useWallet } from '@/context/WalletContext';
import { Shield, Wallet, Lock, Award, Zap, RefreshCw, AlertCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import ThemeToggle from '@/components/ThemeToggle';

const GUARDIAN_PROFILES = [
  {
    id: 1,
    title: 'Guardian No. 1',
    role: 'Relayer Custodian',
    address: process.env.NEXT_PUBLIC_GUARDIAN_1 || '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266',
    duty: 'Holds & operates the Gas Station wallet. Responsible for voter transaction fees and node gas logistics.',
    icon: Zap,
    color: '#0052ff', // Coinbase Blue
  },
  {
    id: 2,
    title: 'Guardian No. 2',
    role: 'Security Auditor',
    address: process.env.NEXT_PUBLIC_GUARDIAN_2 || '0x70997970C51812dc3A010C7d01b50e0d17dc79C8',
    duty: 'Governance multi-sig co-signer. Responsible for verifying UUPS contract upgrade payloads and parameters.',
    icon: Shield,
    color: '#8b5cf6',
  },
  {
    id: 3,
    title: 'Guardian No. 3',
    role: 'Compliance Trustee',
    address: process.env.NEXT_PUBLIC_GUARDIAN_3 || '0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC',
    duty: 'Governs organization registration validation and platform integrity audits.',
    icon: Award,
    color: '#05b169', // Semantic Green
  },
];



function getGuardianIndex(address, dynamicGuardians) {
  const addr = address.toLowerCase();
  const list = dynamicGuardians.length > 0 ? dynamicGuardians : GUARDIAN_PROFILES.map(g => g.address);
  return list.findIndex(g => g.toLowerCase() === addr);
}

export default function AdminAuthPage() {
  const { account, connect, isConnecting, readContract } = useWallet();
  const router = useRouter();

  const [dynamicGuardians, setDynamicGuardians] = useState([]);
  const [guardiansLoaded, setGuardiansLoaded] = useState(false);
  const [checking, setChecking]   = useState(false);
  const [accessError, setAccessError] = useState('');

  useEffect(() => {
    if (!readContract || typeof readContract.getGuardians !== 'function') {
      setGuardiansLoaded(true);
      return;
    }
    setGuardiansLoaded(false);
    readContract.getGuardians()
      .then(list => {
        if (list?.length === 3) {
          setDynamicGuardians(list);
        }
      })
      .catch((err) => {
        console.warn('Failed to load guardians from contract:', err);
      })
      .finally(() => {
        setGuardiansLoaded(true);
      });
  }, [readContract]);

  const verify = useCallback((address) => {
    const idx = getGuardianIndex(address, dynamicGuardians);
    if (idx !== -1) {
      sessionStorage.setItem('active_guardian_id',      String(idx + 1));
      sessionStorage.setItem('active_guardian_address', address);
      sessionStorage.removeItem('simulated_guardian_id');
      sessionStorage.removeItem('simulated_guardian_address');
      router.push('/admin');
    } else {
      setAccessError('Access Denied — connected address is not a registered Aegis Guardian.');
      setChecking(false);
    }
  }, [dynamicGuardians, router]);

  useEffect(() => {
    if (account && guardiansLoaded) {
      verify(account);
    }
  }, [account, guardiansLoaded, verify]);

  const handleConnect = async () => {
    setAccessError('');
    if (account) {
      setChecking(true);
      verify(account);
      return;
    }

    setChecking(true);
    try {
      const success = await connect();
      if (!success) {
        setChecking(false);
        return;
      }
      const accounts = await window.ethereum.request({ method: 'eth_accounts' });
      if (accounts?.[0]) {
        verify(accounts[0]);
      } else {
        setChecking(false);
      }
    } catch (err) {
      console.error(err);
      setAccessError('Wallet connection failed. Please try again.');
      setChecking(false);
    }
  };

  const displayedProfiles = GUARDIAN_PROFILES.map((profile, idx) => ({
    ...profile,
    address: dynamicGuardians[idx] || profile.address
  }));

  return (
    <div className="min-h-screen bg-canvas text-ink flex flex-col items-center justify-center p-6 relative overflow-hidden font-sans">
      <div className="absolute top-6 right-6 z-20">
        <ThemeToggle />
      </div>
      <div className="absolute inset-0 bg-[linear-gradient(to_right,#dee1e620_1px,transparent_1px),linear-gradient(to_bottom,#dee1e620_1px,transparent_1px)] dark:bg-[linear-gradient(to_right,#1e293b50_1px,transparent_1px),linear-gradient(to_bottom,#1e293b50_1px,transparent_1px)] bg-[size:48px_48px] pointer-events-none" />
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[700px] h-[350px] bg-primary/5 dark:bg-primary/10 rounded-full blur-[100px] pointer-events-none" />

      <div className="w-full max-w-4xl space-y-12 z-10">
        
        {/* Header */}
        <div className="text-center space-y-4">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-primary/20 bg-primary/5 text-primary text-xs font-semibold uppercase tracking-wider">
            <Shield size={12} className="animate-pulse" /> Aegis Security Protocol
          </div>
          <h1 className="text-4xl md:text-5xl font-display font-normal tracking-tight text-ink">
            Guardian Portal Gate
          </h1>
          <p className="text-body max-w-lg mx-auto text-sm md:text-base leading-relaxed">
            Multi-signature administrative portal. Cryptographic authorization is required to access gas reserves, relayer nodes, and upgrade hooks.
          </p>
        </div>

        {/* Guardian Node Profiles Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {displayedProfiles.map((profile, idx) => {
            const Icon = profile.icon;
            return (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3, delay: idx * 0.05 }}
                key={profile.id}
                className="bg-canvas border border-hairline hover:border-body dark:hover:border-hairline rounded-xl p-6 relative flex flex-col justify-between shadow-sm group transition-colors"
              >
                <div
                  className="absolute top-0 left-6 right-6 h-[2px] opacity-40 group-hover:opacity-100 transition-opacity"
                  style={{ backgroundColor: profile.color }}
                />
                <div>
                  <div className="flex items-center justify-between mb-5">
                    <div className="p-2.5 rounded-xl bg-surface-soft border border-hairline">
                      <Icon size={18} style={{ color: profile.color }} />
                    </div>
                    <span className="text-[10px] font-mono uppercase tracking-widest px-2 py-0.5 rounded border border-hairline bg-surface-soft text-body">
                      G-{profile.id}
                    </span>
                  </div>
                  <h3 className="text-ink font-semibold text-base mb-1">{profile.title}</h3>
                  <p className="text-[11px] font-semibold mb-3 uppercase tracking-wider" style={{ color: profile.color }}>
                    {profile.role}
                  </p>
                  <p className="text-xs text-body leading-relaxed mb-4">{profile.duty}</p>
                </div>
                <div className="mt-4 pt-4 border-t border-hairline">
                  <p className="text-[10px] text-muted font-mono tracking-tight break-all selection:bg-primary/10">{profile.address}</p>
                </div>
              </motion.div>
            );
          })}
        </div>

        {/* Authorization connect box */}
        <div className="bg-canvas border border-hairline rounded-xl p-8 max-w-xl mx-auto shadow-sm relative overflow-hidden w-full">
          <div className="absolute inset-0 bg-gradient-to-br from-primary/2 to-transparent pointer-events-none" />

          <div className="relative text-center space-y-5">
            <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center mx-auto text-primary">
              <Lock size={18} />
            </div>

            <div className="space-y-1">
              <h2 className="text-lg font-semibold text-ink">Authorized Access Only</h2>
              <p className="text-xs text-body">
                Please connect your Guardian MetaMask account to verify authority.
              </p>
            </div>

            {accessError && (
              <div className="bg-red-50 border border-red-200 dark:bg-red-950/40 dark:border-red-800 rounded-xl p-3 flex gap-2.5 items-start text-left text-xs text-red-700 dark:text-red-300">
                <AlertCircle size={15} className="shrink-0 mt-0.5" />
                <span>{accessError}</span>
              </div>
            )}

            <button
              id="connect-guardian-wallet"
              onClick={handleConnect}
              disabled={isConnecting || checking}
              className="w-full flex items-center justify-center gap-2 bg-primary hover:bg-primary-active text-white font-semibold py-3.5 px-6 rounded-full transition-all disabled:opacity-50 shadow-sm cursor-pointer text-sm"
            >
              {isConnecting || checking ? (
                <>
                  <RefreshCw size={14} className="animate-spin" />
                  <span>Checking signature...</span>
                </>
              ) : (
                <>
                  <Wallet size={14} />
                  <span>Connect Guardian Wallet</span>
                </>
              )}
            </button>
          </div>
        </div>

        <div className="text-center">
          <Link href="/" className="text-xs text-muted hover:text-ink font-semibold">
            ← Return to homepage
          </Link>
        </div>

      </div>
    </div>
  );
}

'use client';
import { useState, useEffect, useRef, useCallback } from 'react';
import { BarChart3, TrendingUp, Users, Activity, Clock, Award, AlertCircle, RefreshCw, Calendar, ShieldCheck, CheckCircle2, Loader2 } from 'lucide-react';

export default function AnalyticsDashboardPage() {
  const [elections, setElections] = useState([]);
  const [selectedElectionId, setSelectedElectionId] = useState(null);
  const [analyticsData, setAnalyticsData] = useState(null);
  const [candidatesMap, setCandidatesMap] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshInterval, setRefreshInterval] = useState(10); // seconds
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [prevVoteCount, setPrevVoteCount] = useState(0);
  const [countAnimation, setCountAnimation] = useState(false);

  // 1. Fetch all elections
  useEffect(() => {
    fetch('/api/elections')
      .then(r => r.json())
      .then(d => {
        if (d.success && d.data && d.data.length > 0) {
          setElections(d.data);
          // Set to active/latest election by default
          const active = d.data.find(e => e.phase === 1) || d.data[d.data.length - 1];
          setSelectedElectionId(active.electionId);
        } else {
          setError('No elections found in the system.');
          setLoading(false);
        }
      })
      .catch(err => {
        setError('Failed to load elections.');
        setLoading(false);
      });
  }, []);

  // 2. Fetch analytics + candidate mappings
  const loadAnalytics = useCallback(async (electionId, silent = false) => {
    if (electionId === null) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      // Fetch election details (for candidate names/info)
      const electionRes = await fetch(`/api/elections/${electionId}`);
      const electionData = await electionRes.json();

      const candidatesInfo = {};
      if (electionData.success && electionData.data && electionData.data.candidates) {
        electionData.data.candidates.forEach(c => {
          candidatesInfo[c.candidateId] = c;
        });
        setCandidatesMap(candidatesInfo);
      }

      // Fetch aggregated analytics data from MongoDB (Serverless Analytics feature)
      const analyticsRes = await fetch(`/api/analytics/${electionId}`);
      const analyticsDataJson = await analyticsRes.json();

      if (analyticsDataJson.success && analyticsDataJson.data) {
        const data = analyticsDataJson.data;

        // Animated vote counter logic
        setPrevVoteCount(prev => {
          if (silent && data.stats.totalVotes > prev) {
            setCountAnimation(true);
            setTimeout(() => setCountAnimation(false), 1000);
          }
          return data.stats.totalVotes;
        });

        setAnalyticsData(data);
        setError('');
      } else {
        setError(analyticsDataJson.error || 'Failed to fetch analytics.');
      }
    } catch (err) {
      console.error(err);
      setError('Connection to analytics service lost.');
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  }, []);

  // Trigger loading analytics when selected election changes
  useEffect(() => {
    if (selectedElectionId !== null) {
      loadAnalytics(selectedElectionId);
    }
  }, [selectedElectionId, loadAnalytics]);

  // 3. Auto-refresh loop
  useEffect(() => {
    if (selectedElectionId === null) return;

    const interval = setInterval(() => {
      loadAnalytics(selectedElectionId, true);
    }, refreshInterval * 1000);

    return () => clearInterval(interval);
  }, [selectedElectionId, refreshInterval, loadAnalytics]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#020617] text-white flex flex-col items-center justify-center">
        <Loader2 size={40} className="text-indigo-500 animate-spin mb-4" />
        <p className="text-slate-400 text-sm font-semibold tracking-wide">Compiling Real-Time Aggregations...</p>
      </div>
    );
  }

  const stats = analyticsData?.stats;
  const hourly = analyticsData?.hourlyDistribution || [];
  const breakdown = analyticsData?.candidateBreakdown || [];
  const activity = analyticsData?.recentActivity || [];
  const election = analyticsData?.election;

  // Calculations for Pure SVG charts
  // Bar Chart calculations
  const maxVotes = Math.max(...breakdown.map(b => b.votes), 1);

  // Time-Series (Line Chart) calculations
  const chartHeight = 160;
  const chartWidth = 500;
  const maxHourlyCount = Math.max(...hourly.map(h => h.count), 1);
  const padding = 25;
  const points = hourly.map((h, i) => {
    const x = padding + (i / Math.max(hourly.length - 1, 1)) * (chartWidth - padding * 2);
    const y = chartHeight - padding - (h.count / maxHourlyCount) * (chartHeight - padding * 2);
    return { x, y, hour: new Date(h.hour).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), count: h.count };
  });

  const linePath = points.length > 0 
    ? `M ${points[0].x} ${points[0].y} ` + points.slice(1).map(p => `L ${p.x} ${p.y}`).join(' ')
    : '';

  const areaPath = points.length > 0
    ? `${linePath} L ${points[points.length - 1].x} ${chartHeight - padding} L ${points[0].x} ${chartHeight - padding} Z`
    : '';

  return (
    <div className="min-h-screen bg-[#020617] text-white flex flex-col font-sans">
      {/* Top Banner / Navigation */}
      <header className="border-b border-slate-900 px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4 backdrop-blur-md bg-slate-950/50 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <BarChart3 size={18} className="text-white" />
          </div>
          <div>
            <h1 className="text-white font-extrabold text-base leading-none">Cloud Analytics Hub</h1>
            <p className="text-slate-500 text-xs">Real-Time MongoDB Aggregated Metrics</p>
          </div>
          <span className="flex h-2 w-2 relative ml-1">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
          </span>
        </div>

        {/* Election Selector & Auto Refresh Control */}
        <div className="flex flex-wrap items-center gap-3 w-full md:w-auto justify-end">
          <div className="flex items-center gap-1.5 bg-slate-900 border border-slate-800 rounded-xl px-2.5 py-1.5 text-xs text-slate-400">
            <Calendar size={13} className="text-indigo-400" />
            <select value={selectedElectionId || ''} onChange={e => setSelectedElectionId(e.target.value)}
              className="bg-transparent border-none outline-none text-white font-semibold pr-4 cursor-pointer">
              {elections.map(el => (
                <option key={el.electionId} value={el.electionId} className="bg-slate-950 text-white">
                  {el.title} ({el.phase === 1 ? 'Voting' : el.phase === 2 ? 'Completed' : 'Registration'})
                </option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-2 bg-slate-900 border border-slate-800 rounded-xl p-1 text-xs">
            <button onClick={() => loadAnalytics(selectedElectionId)} disabled={isRefreshing}
              className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition flex items-center gap-1">
              <RefreshCw size={13} className={isRefreshing ? 'animate-spin' : ''} />
            </button>
            <select value={refreshInterval} onChange={e => setRefreshInterval(Number(e.target.value))}
              className="bg-transparent border-none outline-none text-white font-semibold px-2 cursor-pointer text-xs">
              <option value="5" className="bg-slate-950">5s refresh</option>
              <option value="10" className="bg-slate-950">10s refresh</option>
              <option value="30" className="bg-slate-950">30s refresh</option>
            </select>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-6 md:p-8 max-w-7xl mx-auto w-full space-y-8">

        {/* Election Metadata Card */}
        {election && (
          <div className="bg-gradient-to-r from-indigo-950/20 via-slate-900/40 to-violet-950/20 border border-slate-900 rounded-2xl p-6 backdrop-blur-md">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest px-2.5 py-1 rounded-full bg-indigo-950/40 border border-indigo-900/30">
                  {election.phase === 0 ? 'Phase: Registration' : election.phase === 1 ? 'Phase: Live Voting' : 'Phase: Completed'}
                </span>
                <h2 className="text-2xl font-black text-white mt-3.5">{election.title}</h2>
                <p className="text-slate-400 text-sm mt-1 max-w-2xl">{election.description}</p>
              </div>
              <div className="flex flex-col gap-1 text-xs text-slate-500 font-medium">
                <p className="flex items-center gap-1.5"><Clock size={13} /> Started: {new Date(election.startTime * 1000).toLocaleString()}</p>
                <p className="flex items-center gap-1.5"><Clock size={13} /> Closes: {new Date(election.endTime * 1000).toLocaleString()}</p>
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="flex gap-2 items-center bg-red-950/20 border border-red-700/50 text-red-300 rounded-xl p-4 text-sm">
            <AlertCircle size={16} className="shrink-0" />{error}
          </div>
        )}

        {/* ─── Grid 1: Key Performance Indicators ─── */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">

          {/* Card 1: Total Votes Cast */}
          <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl hover:border-slate-800 transition flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Total Ballots Cast</p>
              <h3 className={`text-3xl font-black text-white transition-all duration-300 ${countAnimation ? 'text-indigo-400 scale-105' : ''}`}>
                {stats?.totalVotes || 0}
              </h3>
            </div>
            <div className="p-3.5 bg-indigo-600/10 rounded-2xl border border-indigo-500/10"><Users size={22} className="text-indigo-400" /></div>
          </div>

          {/* Card 2: Turnout Velocity */}
          <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl hover:border-slate-800 transition flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Voting Velocity</p>
              <h3 className="text-3xl font-black text-emerald-400">{stats?.votesPerMinute || 0} <span className="text-xs text-slate-500 font-medium">/min</span></h3>
            </div>
            <div className="p-3.5 bg-emerald-600/10 rounded-2xl border border-emerald-500/10"><TrendingUp size={22} className="text-emerald-400" /></div>
          </div>

          {/* Card 3: Votes last Hour */}
          <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl hover:border-slate-800 transition flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Active last 1 Hour</p>
              <h3 className="text-3xl font-black text-white">{stats?.votesLast1h || 0}</h3>
            </div>
            <div className="p-3.5 bg-violet-600/10 rounded-2xl border border-violet-500/10"><Activity size={22} className="text-violet-400" /></div>
          </div>

          {/* Card 4: Candidates Count */}
          <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl hover:border-slate-800 transition flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Peak Hour Activity</p>
              <h3 className="text-base font-black text-indigo-300 truncate max-w-[170px]">
                {stats?.peakHour ? `${new Date(stats.peakHour.hour).toLocaleTimeString([], { hour: '2-digit' })} (${stats.peakHour.votes} votes)` : 'No activity'}
              </h3>
            </div>
            <div className="p-3.5 bg-indigo-600/10 rounded-2xl border border-indigo-500/10"><Clock size={22} className="text-indigo-400" /></div>
          </div>
        </div>

        {/* ─── Grid 2: Charts & Leaderboard ─── */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Column A: Charts (Bar + Time Series) */}
          <div className="lg:col-span-8 space-y-8">

            {/* Chart 1: Candidate Vote Distribution */}
            <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl">
              <h3 className="text-lg font-black mb-6 flex items-center gap-2">
                <Award size={18} className="text-indigo-400" /> Candidate Vote Breakdown
              </h3>

              {breakdown.length === 0 ? (
                <div className="h-40 flex items-center justify-center border border-dashed border-slate-800 rounded-xl">
                  <p className="text-slate-500 text-xs font-semibold">Waiting for votes to be cast...</p>
                </div>
              ) : (
                <div className="space-y-5">
                  {breakdown.map(b => {
                    const cand = candidatesMap[b.candidateId];
                    const percent = stats?.totalVotes ? Math.round((b.votes / stats.totalVotes) * 100) : 0;
                    return (
                      <div key={b.candidateId} className="space-y-2">
                        <div className="flex items-center justify-between text-xs font-semibold">
                          <span className="text-white flex items-center gap-2">
                            {cand?.photoUrl ? (
                              <img src={cand.photoUrl} alt="" className="w-5 h-5 rounded-full object-cover border border-slate-800" />
                            ) : (
                              <div className="w-5 h-5 rounded-full bg-indigo-950 flex items-center justify-center text-[10px] text-indigo-300 font-extrabold uppercase">
                                {cand?.name ? cand.name.substring(0, 2) : 'C'}
                              </div>
                            )}
                            {cand?.name || `Candidate #${b.candidateId}`}
                            <span className="text-[10px] text-slate-500 font-medium">({cand?.party || 'Independent'})</span>
                          </span>
                          <span className="text-slate-400">{b.votes} votes ({percent}%)</span>
                        </div>
                        <div className="w-full bg-slate-950 rounded-full h-3 overflow-hidden border border-slate-900">
                          <div className="bg-gradient-to-r from-indigo-500 to-violet-600 h-full rounded-full transition-all duration-500"
                            style={{ width: `${percent}%` }} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Chart 2: Hourly Vote Trend (Time Series) */}
            <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl">
              <h3 className="text-lg font-black mb-6 flex items-center gap-2">
                <TrendingUp size={18} className="text-indigo-400" /> Hourly Turnout Curve
              </h3>

              {hourly.length < 2 ? (
                <div className="h-44 flex items-center justify-center border border-dashed border-slate-800 rounded-xl">
                  <p className="text-slate-500 text-xs font-semibold">More data required to compile line trend...</p>
                </div>
              ) : (
                <div className="w-full">
                  {/* Pure SVG Line Chart */}
                  <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} className="w-full h-auto max-h-52 overflow-visible">
                    <defs>
                      <linearGradient id="chart-area-grad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#6366f1" stopOpacity="0.25" />
                        <stop offset="100%" stopColor="#6366f1" stopOpacity="0" />
                      </linearGradient>
                    </defs>

                    {/* Horizontal grid lines */}
                    <line x1={padding} y1={padding} x2={chartWidth - padding} y2={padding} stroke="#1e293b" strokeDasharray="3 3" />
                    <line x1={padding} y1={chartHeight / 2} x2={chartWidth - padding} y2={chartHeight / 2} stroke="#1e293b" strokeDasharray="3 3" />
                    <line x1={padding} y1={chartHeight - padding} x2={chartWidth - padding} y2={chartHeight - padding} stroke="#1e293b" />

                    {/* Area path */}
                    <path d={areaPath} fill="url(#chart-area-grad)" />

                    {/* Line path */}
                    <path d={linePath} fill="none" stroke="#6366f1" strokeWidth="2.5" />

                    {/* Circles on datapoints */}
                    {points.map((p, i) => (
                      <g key={i}>
                        <circle cx={p.x} cy={p.y} r="4.5" fill="#020617" stroke="#8b5cf6" strokeWidth="2" />
                        <text x={p.x} y={chartHeight - 8} fontSize="8" fill="#475569" textAnchor="middle" fontWeight="bold">
                          {p.hour}
                        </text>
                      </g>
                    ))}
                  </svg>
                </div>
              )}
            </div>

          </div>

          {/* Column B: Recent Activity Timeline */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-slate-900/40 border border-slate-850 p-6 rounded-2xl backdrop-blur-xl h-full flex flex-col max-h-[580px]">
              <h3 className="text-lg font-black mb-6 flex items-center gap-2 border-b border-slate-850 pb-4">
                <Activity size={18} className="text-indigo-400" /> Recent Vote Activities
              </h3>

              {activity.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center p-6 border border-dashed border-slate-800 rounded-xl">
                  <Activity size={24} className="text-slate-600 mb-2 animate-pulse" />
                  <p className="text-slate-500 text-xs font-semibold">No transactions recorded yet.</p>
                </div>
              ) : (
                <div className="flex-1 overflow-y-auto pr-1 space-y-4 custom-scrollbar">
                  {activity.map((act, index) => {
                    const cand = candidatesMap[act.candidateId];
                    return (
                      <div key={act.txHash || index} className="flex gap-3 text-xs leading-relaxed border-l-2 border-slate-800 pl-4 relative">
                        <div className="absolute -left-1.5 top-1.5 w-2.5 h-2.5 rounded-full bg-indigo-500 shadow shadow-indigo-500/40 border border-slate-900" />
                        <div className="flex-1 space-y-1">
                          <p className="text-slate-300">
                            Vote casted for <strong className="text-white font-bold">{cand?.name || `Candidate #${act.candidateId}`}</strong>
                          </p>
                          <div className="flex items-center gap-2 text-[10px] text-slate-500 font-mono">
                            <span className="truncate max-w-[130px]">{act.txHash}</span>
                            <span>·</span>
                            <span>Blk #{act.blockNumber || '---'}</span>
                          </div>
                          <p className="text-[10px] text-slate-600 font-semibold flex items-center gap-1">
                            <Clock size={10} /> {new Date(act.timestamp).toLocaleTimeString()}
                          </p>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

        </div>
      </main>
    </div>
  );
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import Voter from '@/lib/models/Voter';

/**
 * DELETE /api/admin/biometric-cleanup
 * Removes BiometricHash records that have no matching Voter (orphan / bad test records).
 * Also removes records where the nullifierHash is empty or a mock value.
 * 
 * Query params:
 *   - nullifierHash: (optional) delete a specific hash directly
 *   - orphansOnly: (optional, default true) only delete orphan records
 */
export async function DELETE(req) {
  try {
    await connectDB();
    const { searchParams } = new URL(req.url);
    const specificHash = searchParams.get('nullifierHash');

    // If specific hash provided, delete it directly
    if (specificHash) {
      const result = await BiometricHash.deleteOne({ nullifierHash: specificHash });
      return NextResponse.json({
        success: true,
        message: `Deleted biometric record for nullifierHash: ${specificHash}`,
        deletedCount: result.deletedCount,
      });
    }

    // Otherwise, clean up orphan records
    // 1. Get all valid nullifierHashes from voters
    const validVoters = await Voter.find({ nullifierHash: { $exists: true, $ne: '' } }, 'nullifierHash');
    const validHashes = validVoters.map(v => v.nullifierHash);

    // 2. Find all BiometricHash records NOT in valid voter hashes, or with empty/mock hashes
    const orphanRecords = await BiometricHash.find({
      $or: [
        { nullifierHash: { $nin: validHashes } },
        { nullifierHash: '' },
        { nullifierHash: { $regex: '^mock-' } },
      ]
    });

    const orphanHashes = orphanRecords.map(r => r.nullifierHash);

    if (orphanHashes.length === 0) {
      return NextResponse.json({ success: true, message: 'No orphan biometric records found.', deletedCount: 0 });
    }

    const result = await BiometricHash.deleteMany({ nullifierHash: { $in: orphanHashes } });

    return NextResponse.json({
      success: true,
      message: `Cleaned up ${result.deletedCount} orphan biometric record(s).`,
      deletedCount: result.deletedCount,
      deletedHashes: orphanHashes,
    });
  } catch (err) {
    console.error('[admin/biometric-cleanup] Error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

/**
 * POST /api/admin/elections/approve
 * Guardian approves an election → transitions it on-chain from Registration → Voting
 * 
 * Body: { electionId: number, guardianAddress: string, action: 'approve' | 'reject' }
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import Election from '@/lib/models/Election';
import { relayTransitionPhase } from '@/lib/relay';

export async function POST(req) {
  try {
    const { electionId, guardianAddress, action } = await req.json();

    if (electionId === undefined || electionId === null) {
      return NextResponse.json({ error: 'electionId is required' }, { status: 400 });
    }
    if (!guardianAddress) {
      return NextResponse.json({ error: 'guardianAddress is required' }, { status: 400 });
    }
    if (!action || !['approve', 'reject'].includes(action)) {
      return NextResponse.json({ error: 'action must be approve or reject' }, { status: 400 });
    }

    await connectDB();

    const electionDoc = await Election.findOne({ electionId: String(electionId) });
    if (!electionDoc) {
      return NextResponse.json({ error: 'Election not found' }, { status: 404 });
    }

    if (!electionDoc.pendingApproval && action === 'approve') {
      return NextResponse.json({ error: 'This election has not requested go-live approval' }, { status: 400 });
    }

    if (action === 'reject') {
      // Guardian rejects — reset the pending flag, stays in Registration
      await Election.findOneAndUpdate(
        { electionId: String(electionId) },
        { pendingApproval: false }
      );
      return NextResponse.json({
        success: true,
        message: 'Election go-live request rejected. It remains in Registration phase.',
      });
    }

    // ACTION: approve
    // Transition on-chain: Registration(0) → Voting(1)
    const { txHash } = await relayTransitionPhase(String(electionId), 1, electionDoc.orgSlug);

    // Update MongoDB
    await Election.findOneAndUpdate(
      { electionId: String(electionId) },
      {
        phase:              1,
        pendingApproval:    false,
        guardianApproved:   true,
        guardianApprovedBy: guardianAddress,
        guardianApprovedAt: new Date(),
      }
    );

    return NextResponse.json({
      success: true,
      txHash,
      message: `Election #${electionId} approved and is now LIVE for voters!`,
    });
  } catch (err) {
    console.error('[admin/elections/approve POST]', err);
    return NextResponse.json({ error: err.message || 'Approval failed' }, { status: 500 });
  }
}

/**
 * GET  /api/admin/elections  — list elections pending guardian approval
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import Election from '@/lib/models/Election';
import Admin from '@/lib/models/Admin';

export async function GET(req) {
  try {
    await connectDB();

    const { searchParams } = new URL(req.url);
    const filter = searchParams.get('filter') || 'pending'; // pending | all | completed

    let query = {};
    if (filter === 'pending') {
      query = { pendingApproval: true, guardianApproved: false };
    } else if (filter === 'completed') {
      query = { phase: 2 };
    }

    const elections = await Election.find(query)
      .sort({ createdAt: -1 })
      .lean();

    const adminIds = [...new Set(elections.map(e => e.createdBy).filter(Boolean).map(String))];
    const admins = adminIds.length
      ? await Admin.find({ _id: { $in: adminIds } }).lean()
      : [];
    const adminMap = {};
    for (const a of admins) adminMap[String(a._id)] = a;

    const GO_LIVE_APPROVAL_THRESHOLD = 1;

    const enriched = elections.map(e => {
      const admin = e.createdBy ? adminMap[String(e.createdBy)] : null;
      const approvedBy = e.guardianApprovedBy ? [e.guardianApprovedBy] : [];
      return {
        ...e,
        id: e.electionId,
        approvalThreshold: GO_LIVE_APPROVAL_THRESHOLD,
        approvedBy,
        approvalsCount: approvedBy.length,
        org: {
          name: admin?.name || 'Admin',
          email: admin?.email || '',
        },
      };
    });

    return NextResponse.json({ elections: enriched });
  } catch (err) {
    console.error('[admin/elections GET]', err);
    return NextResponse.json({ error: 'Failed to fetch elections' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import Voter from '@/lib/models/Voter';

/**
 * POST /api/admin/fix-biometric-org-scope
 * 
 * One-time migration endpoint: backfills orgSlug and electionId onto
 * BiometricHash records that are missing them, by joining via the Voter model.
 * 
 * This fixes the bug where the TwinOverridesPanel in the dashboard shows
 * "No twin override requests found" even when requests exist — caused by
 * BiometricHash records created before orgSlug/electionId were added to the schema.
 */
export async function POST(req) {
  try {
    await connectDB();

    // Find all BiometricHash records missing orgSlug
    const records = await BiometricHash.find({
      $or: [{ orgSlug: { $exists: false } }, { orgSlug: '' }],
      twinVerificationStatus: { $ne: 'none' },
    }).lean();

    if (records.length === 0) {
      return NextResponse.json({ success: true, message: 'No records need backfilling.', updated: 0 });
    }

    let updated = 0;
    let notFound = 0;

    for (const record of records) {
      const voter = await Voter.findOne({ nullifierHash: record.nullifierHash })
        .select('orgSlug electionId')
        .lean();

      if (voter && (voter.orgSlug || voter.electionId)) {
        await BiometricHash.updateOne(
          { nullifierHash: record.nullifierHash },
          {
            $set: {
              orgSlug: voter.orgSlug || '',
              electionId: voter.electionId || '',
            },
          }
        );
        updated++;
      } else {
        notFound++;
      }
    }

    return NextResponse.json({
      success: true,
      message: `Backfill complete. ${updated} records updated, ${notFound} voter records not found.`,
      updated,
      notFound,
    });
  } catch (err) {
    console.error('[admin/fix-biometric-org-scope] Error:', err);
    return NextResponse.json({ error: err.message || 'Backfill failed.' }, { status: 500 });
  }
}

/**
 * GET /api/admin/fix-indexes
 * One-time migration: drops stale indexes on the voters collection
 * that were created by old schema versions, then resyncs the current schema indexes.
 *
 * Run once by visiting: http://localhost:3000/api/admin/fix-indexes
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import mongoose from 'mongoose';
import Voter from '@/lib/models/Voter';

// Indexes that existed in old schema versions — must be removed
const STALE_INDEXES = [
  'orgId_1_memberId_1',      // old unique compound — causes E11000 on memberId: ""
  'orgId_1_email_1',         // old unique compound replaced by orgSlug_1_email_1
  'nullifierHash_1',         // was globally unique — same voter can appear in multiple elections
  'memberId_1',              // old standalone index
];

export async function GET() {
  try {
    await connectDB();

    const collection = Voter.collection; 

    // 1. List all current indexes
    const existingRaw = await collection.indexes();
    const existing = existingRaw.map(i => i.name);

    const dropped = [];
    const notFound = [];

    // 2. Drop each stale index if it exists
    for (const name of STALE_INDEXES) {
      if (existing.includes(name)) {
        try {
          await collection.dropIndex(name);
          dropped.push(name);
          console.log(`[fix-indexes] Dropped stale index: ${name}`);
        } catch (e) {
          console.warn(`[fix-indexes] Could not drop ${name}:`, e.message);
        }
      } else {
        notFound.push(name);
      }
    }

    // 3. Drop legacy global unique nullifierHash (same voter can be in multiple elections)
    if (existing.includes('nullifierHash_1')) {
      try {
        await collection.dropIndex('nullifierHash_1');
        if (!dropped.includes('nullifierHash_1')) dropped.push('nullifierHash_1');
      } catch (e) {
        console.warn('[fix-indexes] Could not drop nullifierHash_1:', e.message);
      }
    }

    // 4. Ensure per-election nullifier lookup index exists (non-unique)
    await collection.createIndex(
      { orgSlug: 1, electionId: 1, nullifierHash: 1 },
      { name: 'orgSlug_1_electionId_1_nullifierHash_1', background: true },
    );

    // 5. Sync other schema indexes (may recreate stale ones if model cache is old — re-drop after)
    delete mongoose.models.Voter;
    await Voter.syncIndexes();

    // 6. Safety: never keep a global unique nullifierHash index
    const afterSync = (await collection.indexes()).map(i => i.name);
    if (afterSync.includes('nullifierHash_1')) {
      const nh = (await collection.indexes()).find(i => i.name === 'nullifierHash_1');
      if (nh?.unique) {
        await collection.dropIndex('nullifierHash_1');
        dropped.push('nullifierHash_1 (post-sync)');
      }
    }
    console.log('[fix-indexes] syncIndexes complete');

    // 7. Report final index state
    const finalIndexes = (await collection.indexes()).map(i => ({
      name: i.name,
      key:  i.key,
      unique: i.unique ?? false,
      sparse: i.sparse ?? false,
    }));

    return NextResponse.json({
      success: true,
      dropped,
      notFound,
      currentIndexes: finalIndexes,
    });

  } catch (err) {
    console.error('[fix-indexes] ERROR:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

/**
 * POST /api/admin/fix-voters
 * Clears all existing voter registrations so they can be re-registered
 * with the fixed nullifier hash formula (orgSlug:email:secret).
 * 
 * This is a one-time migration endpoint. Only call after deploying the nullifier fix.
 * Body: { confirm: true }
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import Voter from '@/lib/models/Voter';

export async function POST(req) {
  try {
    const { confirm } = await req.json();
    if (!confirm) {
      return NextResponse.json({ error: 'Send { confirm: true } to proceed' }, { status: 400 });
    }

    await connectDB();

    // Reset all registered voters back to pending so they can be
    // bulk-registered again with the corrected nullifier hash
    const result = await Voter.updateMany(
      { status: 'registered' },
      {
        $set: { status: 'pending', nullifierHash: null, onChainTxHash: '', registeredAt: null },
      }
    );

    // Also reset rejected voters
    const rejected = await Voter.updateMany(
      { status: 'rejected' },
      {
        $set: { status: 'pending', nullifierHash: null, onChainTxHash: '', rejectionReason: '', registeredAt: null },
      }
    );

    return NextResponse.json({
      success: true,
      message: 'All voter registrations reset to pending. Re-run bulk-register for each election.',
      resetRegistered: result.modifiedCount,
      resetRejected: rejected.modifiedCount,
    });
  } catch (err) {
    console.error('[admin/fix-voters]', err);
    return NextResponse.json({ error: err.message || 'Reset failed' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { ethers } from 'ethers';

export async function POST() {
  try {
    const rpcUrl = process.env.RPC_URL || 'http://127.0.0.1:8545';
    const provider = new ethers.JsonRpcProvider(rpcUrl);

    // Relayer address: derived from ADMIN_RELAY_PRIVATE_KEY or ADMIN_RELAY_ADDRESS
    const relayerPrivateKey = process.env.ADMIN_RELAY_PRIVATE_KEY;
    let relayerAddress = process.env.ADMIN_RELAY_ADDRESS;
    if (relayerPrivateKey && !relayerAddress) {
      const wallet = new ethers.Wallet(relayerPrivateKey);
      relayerAddress = wallet.address;
    }
    if (!relayerAddress) {
      relayerAddress = '0x70997970C51812dc3A010C7d01b50e0d17dc79C8';
    }

    // Deployer/Gas Station address: derived from DEPLOYER_PRIVATE_KEY
    const deployerPrivateKey = process.env.DEPLOYER_PRIVATE_KEY;
    if (!deployerPrivateKey) {
      return NextResponse.json({ error: 'Deployer private key not configured' }, { status: 400 });
    }

    const deployerWallet = new ethers.Wallet(deployerPrivateKey, provider);
    const deployerAddress = deployerWallet.address;

    // Check if they are the same wallet (e.g. Sepolia configured with same key)
    if (deployerAddress.toLowerCase() === relayerAddress.toLowerCase()) {
      return NextResponse.json({
        success: true,
        message: 'Deployer and Relayer use the same wallet address on Sepolia. Please fund the wallet manually if needed.',
      });
    }

    // Transfer 5.0 ETH from Deployer to Relayer (for local nodes or funded deployer accounts)
    try {
      const tx = await deployerWallet.sendTransaction({
        to: relayerAddress,
        value: ethers.parseEther('5.0'),
      });
      await tx.wait();
      return NextResponse.json({
        success: true,
        message: `Successfully transferred 5.0 ETH from Deployer to Relayer! Tx: ${tx.hash}`,
      });
    } catch (err) {
      console.warn('Auto-transfer failed:', err.message);
      return NextResponse.json({
        error: `Could not auto-transfer: ${err.message}. Please fund ${relayerAddress} manually.`,
      }, { status: 500 });
    }
  } catch (err) {
    console.error('[api/admin/gas/fund POST]', err);
    return NextResponse.json({ error: err.message || 'Funding failed' }, { status: 500 });
  }
}

