import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import Voter from '@/lib/models/Voter';

// GET /api/admin/twin-requests?electionId=...
export async function GET(req) {
  try {
    const { searchParams } = new URL(req.url);
    const electionId = searchParams.get('electionId');

    if (!electionId) {
      return NextResponse.json({ error: 'electionId is required.' }, { status: 400 });
    }

    await connectDB();

    const directQuery = { electionId, twinVerificationStatus: { $ne: 'none' } };
    const directRecords = await BiometricHash.find(directQuery).lean();

    const voterQuery = { electionId };
    const voters = await Voter.find(voterQuery).select('name email nullifierHash').lean();
    const voterMap = new Map(voters.map(v => [v.nullifierHash, v]));
    const nullifierHashes = voters.map(v => v.nullifierHash).filter(Boolean);

    let legacyRecords = [];
    if (nullifierHashes.length > 0) {
      const directNullifiers = new Set(directRecords.map(r => r.nullifierHash));
      legacyRecords = await BiometricHash.find({
        nullifierHash: { $in: nullifierHashes },
        twinVerificationStatus: { $ne: 'none' },
        ...(directNullifiers.size > 0 ? { nullifierHash: { $in: nullifierHashes, $nin: [...directNullifiers] } } : {}),
      }).lean();
    }

    // Merge and de-duplicate by nullifierHash
    const allRecordsMap = new Map();
    for (const r of [...directRecords, ...legacyRecords]) {
      if (!allRecordsMap.has(r.nullifierHash)) {
        allRecordsMap.set(r.nullifierHash, r);
      }
    }
    const allRecords = [...allRecordsMap.values()];

    // Map biometric records to enriched response objects
    const requests = await Promise.all(allRecords.map(async (record) => {
      // Try to find voter info from voterMap (Strategy 2 path) or by direct lookup
      let voter = voterMap.get(record.nullifierHash);
      if (!voter) {
        voter = await Voter.findOne({ nullifierHash: record.nullifierHash }).select('name email').lean();
      }

      // Look up the matched voter's details
      let matchedVoterName = 'Unknown';
      let matchedVoterEmail = record.twinMatchedEmail || 'Unknown';
      if (record.twinMatchedNullifier) {
        const mv = await Voter.findOne({ nullifierHash: record.twinMatchedNullifier }).select('name email').lean();
        if (mv) {
          matchedVoterName = mv.name;
          matchedVoterEmail = mv.email;
        }
      }

      return {
        id: record._id,
        nullifierHash: record.nullifierHash,
        name: voter?.name || 'Unknown Voter',
        email: voter?.email || 'Unknown Email',
        twinVerificationStatus: record.twinVerificationStatus,
        bypassDuplicateCheck: record.bypassDuplicateCheck,
        twinMatchedNullifier: record.twinMatchedNullifier,
        twinMatchedEmail: matchedVoterEmail,
        twinMatchedName: matchedVoterName,
        twinMatchSimilarity: record.twinMatchSimilarity,
        twinNotes: record.twinNotes || '',
        updatedAt: record.updatedAt,
      };
    }));

    return NextResponse.json({ success: true, requests });
  } catch (err) {
    console.error('[admin/twin-requests] GET Error:', err);
    return NextResponse.json({ error: err.message || 'Failed to fetch twin requests.' }, { status: 500 });
  }
}

// POST /api/admin/twin-requests
// Body: { nullifierHash, action: 'approve' | 'reject', notes }
export async function POST(req) {
  try {
    const { nullifierHash, action, notes } = await req.json();

    if (!nullifierHash) {
      return NextResponse.json({ error: 'nullifierHash is required.' }, { status: 400 });
    }
    if (!['approve', 'reject'].includes(action)) {
      return NextResponse.json({ error: 'Action must be approve or reject.' }, { status: 400 });
    }

    await connectDB();

    const record = await BiometricHash.findOne({ nullifierHash });
    if (!record) {
      return NextResponse.json({ error: 'Biometric record not found.' }, { status: 404 });
    }

    if (action === 'approve') {
      record.bypassDuplicateCheck = true;
      record.twinVerificationStatus = 'approved';
    } else {
      record.bypassDuplicateCheck = false;
      record.twinVerificationStatus = 'rejected';
    }

    record.twinNotes = notes || `Manually ${action}d by administrator.`;
    await record.save();

    return NextResponse.json({
      success: true,
      message: `Twin request successfully ${action}d.`,
      record: {
        nullifierHash: record.nullifierHash,
        twinVerificationStatus: record.twinVerificationStatus,
        bypassDuplicateCheck: record.bypassDuplicateCheck,
      }
    });
  } catch (err) {
    console.error('[admin/twin-requests] POST Error:', err);
    return NextResponse.json({ error: err.message || 'Failed to update twin request.' }, { status: 500 });
  }
}

/**
 * POST /api/admin/wipe-data
 * Wipe election-related MongoDB data (keeps organizations).
 * Body: { guardianAddress, confirm: true }
 */
import { NextResponse } from "next/server";
import { ethers } from "ethers";
import connectDB from "@/lib/db";

const COLLECTIONS = [
  "voters",
  "elections",
  "voteactivities",
  "candidates",
  "relaytransactions",
  "voterregistrations",
  "emailotps",
  "biometrichashes",
];

async function isGuardianAddress(address) {
  if (!address || !ethers.isAddress(address)) return false;
  const normalized = address.toLowerCase();
  const envGuardians = [
    process.env.ADMIN_RELAY_ADDRESS,
    process.env.GUARDIAN_1_ADDRESS,
    process.env.GUARDIAN_2_ADDRESS,
    process.env.GUARDIAN_3_ADDRESS,
  ]
    .filter(Boolean)
    .map((a) => a.toLowerCase());
  return envGuardians.includes(normalized);
}

export async function POST(req) {
  try {
    const { guardianAddress, confirm } = await req.json();

    if (!confirm) {
      return NextResponse.json(
        { error: "Send { confirm: true } to proceed" },
        { status: 400 },
      );
    }

    if (!(await isGuardianAddress(guardianAddress))) {
      return NextResponse.json(
        { error: "Unauthorized — guardian wallet required" },
        { status: 403 },
      );
    }

    await connectDB();
    const db = (await import("mongoose")).default.connection.db;

    const deleted = {};
    for (const name of COLLECTIONS) {
      try {
        const result = await db.collection(name).deleteMany({});
        deleted[name] = result.deletedCount;
      } catch {
        deleted[name] = 0;
      }
    }

    const total = Object.values(deleted).reduce((a, b) => a + b, 0);

    return NextResponse.json({
      success: true,
      deleted,
      total,
      message:
        total === 0
          ? "Database was already empty"
          : `Wiped ${total} document(s). Create a new election and re-upload voters.`,
    });
  } catch (err) {
    console.error("[admin/wipe-data]", err);
    return NextResponse.json(
      { error: err.message || "Wipe failed" },
      { status: 500 },
    );
  }
}

/**
 * GET /api/analytics/[electionId]
 * Real-time analytics for a specific election.
 * Returns hourly distribution, candidate breakdown, activity feed, and stats.
 * 
 * This is the "Serverless Real-Time Analytics" cloud integration —
 * uses MongoDB aggregation pipeline instead of slow blockchain queries.
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import VoteActivity from '@/lib/models/VoteActivity';
import Election from '@/lib/models/Election';
import Voter from '@/lib/models/Voter';
import BiometricHash from '@/lib/models/BiometricHash';

export async function GET(request, { params }) {
  try {
    await connectDB();
    const { electionId } = await params;
    const eid = String(electionId);

    // 1. Hourly vote distribution (time-series data for chart)
    const hourlyDistribution = await VoteActivity.aggregate([
      { $match: { electionId: eid } },
      {
        $group: {
          _id: {
            $dateToString: { format: '%Y-%m-%dT%H:00:00', date: '$timestamp' },
          },
          count: { $sum: 1 },
        },
      },
      { $sort: { _id: 1 } },
      {
        $project: {
          _id: 0,
          hour: '$_id',
          count: 1,
        },
      },
    ]);

    // 2. Per-candidate vote breakdown (bar chart data)
    const candidateBreakdown = await VoteActivity.aggregate([
      { $match: { electionId: eid } },
      {
        $group: {
          _id: '$candidateId',
          votes: { $sum: 1 },
          firstVote: { $min: '$timestamp' },
          lastVote: { $max: '$timestamp' },
        },
      },
      { $sort: { votes: -1 } },
      {
        $project: {
          _id: 0,
          candidateId: '$_id',
          votes: 1,
          firstVote: 1,
          lastVote: 1,
        },
      },
    ]);

    // 3. Total stats
    const totalVotes = await VoteActivity.countDocuments({ electionId: eid });
    const votesLast1h = await VoteActivity.countDocuments({
      electionId: eid,
      timestamp: { $gte: new Date(Date.now() - 60 * 60 * 1000) },
    });
    const votesLast24h = await VoteActivity.countDocuments({
      electionId: eid,
      timestamp: { $gte: new Date(Date.now() - 24 * 60 * 60 * 1000) },
    });

    // 4. Peak voting hour
    const peakHour = hourlyDistribution.length > 0
      ? hourlyDistribution.reduce((max, h) => h.count > max.count ? h : max, hourlyDistribution[0])
      : null;

    // 5. Recent activity feed (last 50 events)
    const recentActivity = await VoteActivity.find({ electionId: eid })
      .sort({ timestamp: -1 })
      .limit(50)
      .select('candidateId txHash blockNumber timestamp')
      .lean();

    // 6. Election metadata
    const election = await Election.findOne({ electionId: eid }).lean();

    // 7. Votes per minute (velocity) — last 10 minutes
    const tenMinAgo = new Date(Date.now() - 10 * 60 * 1000);
    const recentCount = await VoteActivity.countDocuments({
      electionId: eid,
      timestamp: { $gte: tenMinAgo },
    });
    const votesPerMinute = (recentCount / 10).toFixed(2);

    // 8. Demographics (aggregated from Voter collection — NOT linked to individual votes)
    // PRIVACY: Demographics are computed from the voter ROSTER, not correlated
    // with individual vote records. This means we know "40% of registered voters
    // are female" but NOT "this specific vote was cast by a female voter."
    const registeredVoters = await Voter.find({ electionId: eid, status: 'registered' }).lean();
    const biometrics = await BiometricHash.find({
      nullifierHash: { $in: registeredVoters.map(v => v.nullifierHash).filter(Boolean) }
    }).lean();

    const bioMap = {};
    for (const b of biometrics) {
      bioMap[b.nullifierHash] = b;
    }

    const ageGroups = {
      '18-25': 0,
      '26-35': 0,
      '36-50': 0,
      '50+': 0,
      'Unknown': 0
    };

    const rosterGenders = {
      'Male': 0,
      'Female': 0,
      'Other': 0,
      'Unknown': 0
    };

    const rekognitionGenders = {
      'Male': 0,
      'Female': 0,
      'Unknown': 0
    };

    let genderMatches = 0;
    let genderMismatches = 0;
    let genderCompareUnknowns = 0;

    for (const voter of registeredVoters) {
      // Age groups
      if (voter.age) {
        const age = voter.age;
        if (age >= 18 && age <= 25) ageGroups['18-25']++;
        else if (age >= 26 && age <= 35) ageGroups['26-35']++;
        else if (age >= 36 && age <= 50) ageGroups['36-50']++;
        else if (age > 50) ageGroups['50+']++;
        else ageGroups['Unknown']++;
      } else {
        ageGroups['Unknown']++;
      }

      // Roster genders
      let rGender = 'Unknown';
      if (voter.gender) {
        const g = voter.gender.trim().toLowerCase();
        if (g === 'male' || g === 'm') { rGender = 'Male'; rosterGenders['Male']++; }
        else if (g === 'female' || g === 'f') { rGender = 'Female'; rosterGenders['Female']++; }
        else if (g) { rGender = 'Other'; rosterGenders['Other']++; }
        else { rosterGenders['Unknown']++; }
      } else {
        rosterGenders['Unknown']++;
      }

      // Rekognition genders
      const bio = bioMap[voter.nullifierHash];
      let awsGender = 'Unknown';
      if (bio && bio.faceAttributes && bio.faceAttributes.gender) {
        const g = bio.faceAttributes.gender.trim().toLowerCase();
        if (g === 'male') { awsGender = 'Male'; rekognitionGenders['Male']++; }
        else if (g === 'female') { awsGender = 'Female'; rekognitionGenders['Female']++; }
        else { rekognitionGenders['Unknown']++; }
      } else {
        rekognitionGenders['Unknown']++;
      }

      // Gender Match checks
      if (rGender !== 'Unknown' && awsGender !== 'Unknown') {
        if (rGender.toLowerCase() === awsGender.toLowerCase()) {
          genderMatches++;
        } else {
          genderMismatches++;
        }
      } else {
        genderCompareUnknowns++;
      }
    }

    // Re-vote stats (V3 feature)
    const revoteCount = await VoteActivity.countDocuments({ electionId: eid, isRevote: true });

    return NextResponse.json({
      success: true,
      data: {
        electionId: eid,
        election: election ? {
          title: election.title,
          description: election.description,
          phase: election.phase,
          startTime: election.startTime,
          endTime: election.endTime,
        } : null,
        stats: {
          totalVotes,
          votesLast1h,
          votesLast24h,
          votesPerMinute: Number(votesPerMinute),
          peakHour: peakHour ? { hour: peakHour.hour, votes: peakHour.count } : null,
          candidateCount: candidateBreakdown.length,
          revoteCount,
        },
        hourlyDistribution,
        candidateBreakdown,
        recentActivity: recentActivity.map(v => ({
          candidateId: v.candidateId,
          txHash: v.txHash,
          blockNumber: v.blockNumber,
          timestamp: v.timestamp,
          isRevote: v.isRevote || false,
        })),
        demographics: {
          registeredVoterCount: registeredVoters.length,
          ageGroups,
          rosterGenders,
          rekognitionGenders,
          genderMatchStats: {
            matches: genderMatches,
            mismatches: genderMismatches,
            unknowns: genderCompareUnknowns,
            matchRate: (genderMatches + genderMismatches) > 0
              ? Number(((genderMatches / (genderMatches + genderMismatches)) * 100).toFixed(1))
              : 100
          },
          // PRIVACY: location analytics removed — GPS data is no longer collected
        }
      },
    });
  } catch (err) {
    console.error('[analytics]', err);
    return NextResponse.json(
      { success: false, error: err.message },
      { status: 500 }
    );
  }
}

/**
 * GET /api/assets/party-symbols/... | /api/assets/candidates/...
 * Public read proxy for ballot images — uses IAM credentials, no public S3 bucket needed.
 */
import { NextResponse } from 'next/server';
import { getObjectFromS3 } from '@/lib/s3';
import { isPublicAssetKey } from '@/lib/urlUtils';

export async function GET(_req, { params }) {
  try {
    const { path: segments } = await params;
    const parts = Array.isArray(segments) ? segments : [segments].filter(Boolean);

    if (!parts.length || parts.some((p) => p === '..' || p === '.')) {
      return NextResponse.json({ error: 'Invalid path' }, { status: 400 });
    }

    const key = parts.map((segment) => decodeURIComponent(segment)).join('/');

    if (!isPublicAssetKey(key)) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    const { body, contentType, cacheControl } = await getObjectFromS3(key);

    return new NextResponse(body, {
      status: 200,
      headers: {
        'Content-Type': contentType,
        'Cache-Control': cacheControl,
        'X-Content-Type-Options': 'nosniff',
      },
    });
  } catch (err) {
    if (err?.name === 'NoSuchKey' || err?.$metadata?.httpStatusCode === 404) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }
    if (err.message === 'Asset path not allowed') {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }
    console.error('[assets GET]', err);
    return NextResponse.json({ error: 'Failed to load asset' }, { status: 500 });
  }
}

/**
 * GET /api/audit/verify?txHash=0x...
 * Public vote verification — confirm a transaction was recorded on-chain.
 *
 * PRIVACY — RECEIPT-FREENESS:
 *   This endpoint intentionally does NOT return candidateId or candidateName.
 *   Exposing the vote choice via txHash would allow coercers to verify a
 *   voter's selection, breaking coercion resistance. The endpoint confirms
 *   only that a vote transaction exists and is valid.
 */
import { NextResponse } from 'next/server';
import { ethers } from 'ethers';
import connectDB from '@/lib/db';
import VoteActivity from '@/lib/models/VoteActivity';
import Election from '@/lib/models/Election';

async function getReadContract() {
  const abi = (
    await import('@/lib/contracts/VotingV1.json', { assert: { type: 'json' } })
  ).default.abi;
  const provider = new ethers.JsonRpcProvider(
    process.env.RPC_URL || 'http://127.0.0.1:8545',
  );
  return new ethers.Contract(
    process.env.NEXT_PUBLIC_CONTRACT_ADDRESS,
    abi,
    provider,
  );
}

export async function GET(req) {
  try {
    const { searchParams } = new URL(req.url);
    const txHash = (searchParams.get('txHash') || '').trim();

    if (!txHash || !txHash.startsWith('0x') || txHash.length !== 66) {
      return NextResponse.json(
        { success: false, error: 'A valid transaction hash is required (0x + 64 hex chars).' },
        { status: 400 },
      );
    }

    await connectDB();

    const provider = new ethers.JsonRpcProvider(
      process.env.RPC_URL || 'http://127.0.0.1:8545',
    );

    const [receipt, activity] = await Promise.all([
      provider.getTransactionReceipt(txHash).catch(() => null),
      VoteActivity.findOne({ txHash }).lean(),
    ]);

    if (!receipt && !activity) {
      return NextResponse.json({
        success: false,
        verified: false,
        error: 'Transaction not found on-chain or in the vote ledger.',
      });
    }

    const contractAddress = (process.env.NEXT_PUBLIC_CONTRACT_ADDRESS || '').toLowerCase();
    const onContract = receipt
      ? receipt.to?.toLowerCase() === contractAddress
      : false;
    const status = receipt?.status === 1 ? 'success' : receipt ? 'failed' : 'unknown';

    let electionId = activity?.electionId ?? null;
    let electionTitle = null;
    let blockNumber = receipt?.blockNumber ?? activity?.blockNumber ?? null;
    let timestamp = activity?.timestamp ?? null;

    // Parse VoteCast event from receipt logs if MongoDB has no record
    // PRIVACY: We extract electionId for context, but NOT candidateId
    if (receipt && onContract && electionId == null) {
      const iface = new ethers.Interface(
        (await import('@/lib/contracts/VotingV1.json', { assert: { type: 'json' } })).default.abi,
      );
      for (const log of receipt.logs) {
        try {
          const parsed = iface.parseLog(log);
          if (parsed?.name === 'VoteCast') {
            electionId = parsed.args[0]; // bytes32 hex string
            // candidateId intentionally NOT extracted — receipt-freeness
            break;
          }
        } catch {
          // not our event
        }
      }
    }

    if (electionId != null) {
      const election = await Election.findOne({ electionId }).lean();
      if (election) {
        electionTitle = election.title;
      }
      // PRIVACY: candidateId/candidateName intentionally NOT looked up.
      // Exposing vote choice via txHash breaks receipt-freeness.
    }

    if (!timestamp && blockNumber) {
      try {
        const block = await provider.getBlock(blockNumber);
        if (block?.timestamp) timestamp = new Date(block.timestamp * 1000);
      } catch {
        // optional
      }
    }

    const verified = Boolean(
      (receipt && receipt.status === 1 && onContract) || activity,
    );

    return NextResponse.json({
      success: true,
      verified,
      txHash,
      status,
      onContract,
      blockNumber,
      timestamp,
      electionId,
      electionTitle,
      // candidateId and candidateName intentionally omitted for receipt-freeness
      message: verified
        ? 'Vote transaction verified on the blockchain. For voter privacy, the candidate choice is not disclosed.'
        : 'Transaction found but could not be fully verified as a successful vote.',
    });
  } catch (err) {
    console.error('[audit/verify]', err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

/**
 * POST /api/auth/send-otp
 * Voter OTP for mobile app voting (election-scoped, no organization).
 */
import { NextResponse } from "next/server";
import connectDB from "@/lib/db";
import Voter from "@/lib/models/Voter";
import Election from "@/lib/models/Election";
import EmailOTP from "@/lib/models/EmailOTP";
import { sendOTPEmail } from "@/lib/mailer";
import { preflightCheck } from "@/lib/preflightCache";
import { rateLimit } from "@/lib/rateLimit";
import { computeNullifierHash } from "@/lib/voterIdentity";
import bcrypt from "bcryptjs";
import crypto from "crypto";

const otpLimiter = rateLimit({
  windowMs: 60_000,
  max: 5,
  keyPrefix: "send-otp",
  message: "Too many OTP requests. Please wait before trying again.",
});

export async function POST(req) {
  const limited = otpLimiter(req);
  if (limited) return limited;

  try {
    const { email, electionId } = await req.json();

    if (!email || electionId === undefined || electionId === null || electionId === "") {
      return NextResponse.json(
        { error: "email and electionId are required." },
        { status: 400 },
      );
    }

    await connectDB();
    const eid = String(electionId);
    const cleanEmail = email.toLowerCase().trim();

    const election = await Election.findOne({ electionId: eid }).lean();
    if (!election) {
      return NextResponse.json({ error: "Election not found." }, { status: 404 });
    }

    const voter = await Voter.findOne({ electionId: eid, email: cleanEmail });
    if (!voter) {
      return NextResponse.json(
        {
          error:
            "Email is not registered for this election. Please check with your election admin.",
        },
        { status: 404 },
      );
    }

    if (voter.status === "rejected") {
      return NextResponse.json(
        {
          error: `Voter registration was rejected: ${voter.rejectionReason || "unknown reason"}.`,
        },
        { status: 403 },
      );
    }

    let nullifierHash = voter.nullifierHash;
    if (!nullifierHash) {
      nullifierHash = computeNullifierHash(cleanEmail);
    }

    if (voter.status === "registered") {
      const checkResult = await preflightCheck(nullifierHash, eid);
      if (!checkResult.allowed) {
        return NextResponse.json({ error: checkResult.reason }, { status: 403 });
      }
    }

    const otp = String(crypto.randomInt(100000, 999999));
    const otpHash = await bcrypt.hash(otp, 8);
    const expiresAt = new Date(Date.now() + 5 * 60 * 1000);

    await EmailOTP.findOneAndUpdate(
      { email: cleanEmail, purpose: "vote", electionId: eid },
      {
        email: cleanEmail,
        otp: otpHash,
        electionId: eid,
        purpose: "vote",
        expiresAt,
        used: false,
        attempts: 0,
      },
      { upsert: true, returnDocument: "after" },
    );

    await sendOTPEmail(cleanEmail, otp, "vote", election.title || "Block Vote");

    return NextResponse.json({
      success: true,
      message: "OTP sent successfully to your email.",
      expiresAt,
    });
  } catch (err) {
    console.error("[send-otp]", err);
    return NextResponse.json(
      { error: err.message || "Failed to send OTP." },
      { status: 500 },
    );
  }
}

/**
 * POST /api/auth/verify-otp
 * Mobile app: verify email OTP + biometric token, then relay castVote.
 */
import { NextResponse } from "next/server";
import connectDB from "@/lib/db";
import Voter from "@/lib/models/Voter";
import EmailOTP from "@/lib/models/EmailOTP";
import { preflightCheck } from "@/lib/preflightCache";
import { relayCastVote, relayRegisterVoter, isVoterRegisteredOnChain } from "@/lib/relay";
import { sendVoteReceiptEmail } from "@/lib/mailer";
import bcrypt from "bcryptjs";
import { verifyBiometricToken } from "@/lib/biometric";
