export async function POST(req) {
  try {
    const { email, otp, electionId, candidateId, biometricToken: bodyToken } = await req.json();
    const biometricToken = req.headers.get("x-biometric-token") || bodyToken;

    if (
      !email ||
      !otp ||
      electionId === undefined ||
      electionId === null ||
      electionId === "" ||
      candidateId === undefined
    ) {
      return NextResponse.json(
        { error: "email, otp, electionId, and candidateId are required." },
        { status: 400 },
      );
    }

    await connectDB();

    const cleanEmail = email.toLowerCase().trim();
    const eid = String(electionId);

    const record = await EmailOTP.findOne({
      email: cleanEmail,
      purpose: "vote",
      electionId: eid,
    });

    if (!record || record.used) {
      return NextResponse.json(
        {
          error:
            "OTP has expired or has already been used. Please request a new one.",
        },
        { status: 400 },
      );
    }

    if (new Date() > record.expiresAt) {
      return NextResponse.json(
        { error: "OTP has expired. Please request a new one." },
        { status: 400 },
      );
    }

    if (record.attempts >= 3) {
      return NextResponse.json(
        { error: "Too many incorrect attempts. Please request a new OTP." },
        { status: 400 },
      );
    }

    const validOTP = await bcrypt.compare(String(otp).trim(), record.otp);
    if (!validOTP) {
      record.attempts += 1;
      await record.save();
      const remaining = 3 - record.attempts;
      return NextResponse.json(
        {
          error: `Incorrect OTP. ${remaining} attempt${remaining !== 1 ? "s" : ""} remaining.`,
        },
        { status: 400 },
      );
    }

    const voter = await Voter.findOne({ electionId: eid, email: cleanEmail });
    if (!voter) {
      return NextResponse.json(
        {
          error:
            "Email is not registered for this election. Please check with your election admin.",
        },
        { status: 404 },
      );
    }

    let nullifierHash = voter.nullifierHash;

    if (voter.status === "pending" || !nullifierHash) {
      nullifierHash = computeNullifierHash(cleanEmail);

      try {
        const alreadyOnChain = await isVoterRegisteredOnChain(eid, nullifierHash);
        if (alreadyOnChain) {
          await Voter.findByIdAndUpdate(voter._id, {
            status: "registered",
            nullifierHash,
            registeredAt: new Date(),
            onChainTxHash: "auto-linked",
            rejectionReason: "",
          });
          voter.status = "registered";
          voter.nullifierHash = nullifierHash;
        } else {
          const { txHash } = await relayRegisterVoter(eid, nullifierHash);
          await Voter.findByIdAndUpdate(voter._id, {
            status: "registered",
            nullifierHash,
            registeredAt: new Date(),
            onChainTxHash: txHash,
            rejectionReason: "",
          });
          voter.status = "registered";
          voter.nullifierHash = nullifierHash;
        }
      } catch (regErr) {
        console.error(`[verify-otp] Auto-registration failed for ${cleanEmail}:`, regErr.message);
        return NextResponse.json(
          {
            error:
              "Your voter registration could not be finalized on the blockchain. Please contact your election admin.",
          },
          { status: 403 },
        );
      }
    }

    if (voter.status !== "registered") {
      return NextResponse.json(
        {
          error: `Voter registration status is "${voter.status}". Please contact your admin.`,
        },
        { status: 403 },
      );
    }

    if (!voter.nullifierHash) {
      return NextResponse.json(
        {
          error:
            "Voter on-chain registration is incomplete. Please contact your admin.",
        },
        { status: 403 },
      );
    }

    nullifierHash = voter.nullifierHash;

    if (!biometricToken) {
      return NextResponse.json(
        {
          error:
            "Biometric session verification required. Please verify your face first.",
        },
        { status: 403 },
      );
    }

    const decodedBiometric = verifyBiometricToken(biometricToken);
    if (!decodedBiometric || !decodedBiometric.authenticated) {
      return NextResponse.json(
        {
          error:
            "Biometric authentication is invalid. Please verify your face again.",
        },
        { status: 403 },
      );
    }

    const checkResult = await preflightCheck(nullifierHash, eid);
    if (!checkResult.allowed) {
      return NextResponse.json({ error: checkResult.reason }, { status: 403 });
    }

    const { txHash } = await relayCastVote(eid, Number(candidateId), nullifierHash);

    const Election = (await import("@/lib/models/Election")).default;
    const election = await Election.findOne({ electionId: eid }).lean();

    const baseUrl =
      process.env.NEXT_PUBLIC_APP_URL ||
      process.env.APP_URL ||
      "http://localhost:3000";
    const verifyUrl = `${baseUrl}/verify?txHash=${encodeURIComponent(txHash)}`;

    try {
      await sendVoteReceiptEmail(cleanEmail, {
        electionTitle: election?.title || `Election #${eid.slice(0, 10)}`,
        txHash,
        verifyUrl,
      });
    } catch (mailErr) {
      console.error("[verify-otp] receipt email failed:", mailErr);
    }

    record.used = true;
    await record.save();

    return NextResponse.json({
      success: true,
      message: "Vote successfully relayed and recorded on the blockchain.",
      txHash,
      verifyUrl,
    });
  } catch (err) {
    console.error("[verify-otp]", err);

    const reason = err?.reason || err?.revert?.args?.[0] || err?.message || "Verification failed.";
    let userMessage = reason;

    if (reason.includes("voter not registered")) {
      userMessage =
        "Your voter registration is not yet finalized on the blockchain. Please contact your election admin.";
    } else if (reason.includes("already voted")) {
      userMessage =
        "Your vote has already been recorded on the blockchain for this election.";
    } else if (
      reason.includes("election not active") ||
      reason.includes("not in voting phase") ||
      reason.includes("not voting phase")
    ) {
      userMessage = "This election is no longer accepting votes.";
    } else if (reason.includes("invalid candidate")) {
      userMessage = "The selected candidate is not valid for this election.";
    }

    return NextResponse.json({ error: userMessage }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import Voter from '@/lib/models/Voter';
import { normalizeLandmarks, isAWSConfigured, getRekognitionClient, issueBiometricToken } from '@/lib/biometric';
import { DetectFacesCommand } from '@aws-sdk/client-rekognition';

export async function POST(req) {
  try {
    const { nullifierHash, landmarks, image, faceConfidence = 0.98 } = await req.json();

    if (!nullifierHash) {
      return NextResponse.json(
        { error: 'nullifierHash is required.' },
        { status: 400 }
      );
    }

    const awsConfigured = isAWSConfigured();
    if (awsConfigured && !image) {
      return NextResponse.json(
        { error: 'A face photo is required for biometric registration.' },
        { status: 400 }
      );
    }
    if (!awsConfigured && !landmarks) {
      return NextResponse.json(
        { error: 'Landmarks are required for local biometric fallback.' },
        { status: 400 }
      );
    }

    await connectDB();

    // 1. Verify the voter exists and is in the system
    const voter = await Voter.findOne({ nullifierHash });
    if (!voter) {
      return NextResponse.json(
        { error: 'Voter registration not found. Please register first.' },
        { status: 404 }
      );
    }

    // 2. AWS Rekognition Face Detection & Liveness Check (if image provided)
    let confidence = Number(faceConfidence);
    let provider = 'local-canvas';
    let ipfsCid = '';
    let faceAttributes = null;
    let faceId = '';
    let twinVerificationStatus = 'none';

    if (image) {
      const rekognition = getRekognitionClient();
      try {
        const base64Data = image.replace(/^data:image\/\w+;base64,/, "");
        const imageBuffer = Buffer.from(base64Data, 'base64');

        const detectCmd = new DetectFacesCommand({
          Image: { Bytes: imageBuffer },
          Attributes: ['ALL']
        });

        const detectRes = await rekognition.send(detectCmd);
        if (!detectRes.FaceDetails || detectRes.FaceDetails.length === 0) {
          return NextResponse.json(
            { error: 'No face detected in registration photo. Please capture a clear face.' },
            { status: 400 }
          );
        }
        if (detectRes.FaceDetails.length > 1) {
          return NextResponse.json(
            { error: 'Multiple faces detected. Please ensure only one person is in the frame.' },
            { status: 400 }
          );
        }

        const face = detectRes.FaceDetails[0];
        if (face.Confidence < 90) {
          return NextResponse.json(
            { error: `Face detection confidence is too low (${Math.round(face.Confidence)}%). Please ensure your face is fully visible.` },
            { status: 400 }
          );
        }

        // Lighting check (Quality.Brightness)
        if (face.Quality && face.Quality.Brightness < 30) {
          return NextResponse.json(
            { error: 'Liveness check failed: Lighting is too low. Please turn on lights or move to a brighter area.' },
            { status: 400 }
          );
        }

        // Eyeglasses & Sunglasses check
        const wearsGlasses = (face.Eyeglasses && face.Eyeglasses.Value === true && face.Eyeglasses.Confidence > 80) ||
                             (face.Sunglasses && face.Sunglasses.Value === true && face.Sunglasses.Confidence > 80);
        if (wearsGlasses) {
          return NextResponse.json(
            { error: 'Liveness check failed: Please remove your glasses or sunglasses for a clean biometric scan.' },
            { status: 400 }
          );
        }

        confidence = face.Confidence / 100;
        provider = 'aws-rekognition';

        // Extract real face attributes
        faceAttributes = {
          faceConfidence: face.Confidence,
          gender: face.Gender?.Value,
          genderConfidence: face.Gender?.Confidence,
          ageRange: face.AgeRange ? `${face.AgeRange.Low} - ${face.AgeRange.High} years old` : 'Unknown',
          brightness: face.Quality?.Brightness,
          sharpness: face.Quality?.Sharpness,
        };
      } catch (awsErr) {
        console.error('[biometric/register] AWS Rekognition error:', awsErr);
        return NextResponse.json(
          { error: 'Face detection failed. Please retake your photo in good lighting.' },
          { status: 500 }
        );
      }

      // Check duplicate face in collection
      try {
        const { searchFaceFromBase64, indexFaceFromBase64 } = await import('@/lib/aws');

        const existingRecord = await BiometricHash.findOne({ nullifierHash });
        const hasTwinBypass = existingRecord && (existingRecord.bypassDuplicateCheck || existingRecord.twinVerificationStatus === 'approved');

        const matches = await searchFaceFromBase64(image, 5, 85);
        const otherMatch = matches.find(m => m.nullifierHash !== nullifierHash);

        if (otherMatch && !hasTwinBypass) {
          let matchedEmail = '';
          const matchedVoter = await Voter.findOne({ nullifierHash: otherMatch.nullifierHash });
          if (matchedVoter) {
            matchedEmail = matchedVoter.email;
          }

          // Save pending twin record (include org scoping for admin panel queries)
          await BiometricHash.findOneAndUpdate(
            { nullifierHash },
            {
              nullifierHash,
              biometricHash: `pending-twin-override-for-${otherMatch.nullifierHash}`,
              faceConfidence: confidence,
              provider: 'aws-rekognition',
              registeredAt: new Date(),
              twinVerificationStatus: 'pending',
              twinMatchedNullifier: otherMatch.nullifierHash,
              twinMatchedEmail: matchedEmail,
              twinMatchSimilarity: Math.round(otherMatch.similarity),
              twinNotes: 'Automatically flagged: high similarity match with another registered face.',
              faceAttributes,
              electionId: voter.electionId || '',
            },
            { upsert: true }
          );

          return NextResponse.json({
            error: 'DUPLICATE_FACE_DETECTED',
            message: 'This face matches another registered voter. If you are an identical twin, please request a Twin Verification Override.',
            similarity: Math.round(otherMatch.similarity),
            matchedNullifier: otherMatch.nullifierHash
          }, { status: 409 });
        }

        // Proceed to index face in AWS Collection
        const indexRes = await indexFaceFromBase64(nullifierHash, image);
        faceId = indexRes?.faceId || '';
        twinVerificationStatus = hasTwinBypass ? 'approved' : 'none';

      } catch (searchErr) {
        console.error('[biometric/register] AWS Rekognition search/index error:', searchErr);
      }

      // Pin face registration to IPFS
      try {
        const { pinJSON } = await import('@/lib/ipfs');
        ipfsCid = await pinJSON(
          {
            nullifierHash,
            image,
            registeredAt: new Date().toISOString(),
          },
          `biometric-voter-${nullifierHash}`,
          { nullifierHash, type: 'biometric-voter' }
        );
        console.log(`[biometric/register] Face metadata pinned to IPFS CID: ${ipfsCid}`);
      } catch (ipfsErr) {
        console.error('[biometric/register] IPFS pin failed:', ipfsErr);
        // Fallback placeholder CID if Pinata configuration is missing or fails
        ipfsCid = `mock-ipfs-cid-${nullifierHash}`;
      }
    }

    // 3. Normalize face landmark coordinates (for local similarity fallbacks)
    const normalized = normalizeLandmarks(landmarks);
    if (!normalized) {
      return NextResponse.json(
        { error: 'Invalid face landmarks. Face could not be normalized.' },
        { status: 400 }
      );
    }

    // 4. Store the IPFS CID (or serialized ratios) as the biometricHash
    const biometricHashData = ipfsCid || JSON.stringify(normalized);

    const record = await BiometricHash.findOneAndUpdate(
      { nullifierHash },
      {
        nullifierHash,
        biometricHash: biometricHashData,
        faceConfidence: confidence,
        provider,
        registeredAt: new Date(),
        faceId,
        twinVerificationStatus,
        electionId: voter.electionId || '',
      },
      { upsert: true, returnDocument: 'after' }
    );

    // Success -> Issue 60s JWT token for immediate redirect
    const token = issueBiometricToken(nullifierHash);

    return NextResponse.json({
      success: true,
      message: 'Biometric profile registered successfully.',
      data: {
        nullifierHash: record.nullifierHash,
        registeredAt: record.registeredAt,
        provider: record.provider,
        ipfsCid: ipfsCid || null,
        faceAttributes,
        token
      },
    });
  } catch (err) {
    console.error('[biometric/register]', err);
    return NextResponse.json(
      { error: err.message || 'Biometric registration failed.' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import { issueBiometricToken } from '@/lib/biometric';

/**
 * GET /api/biometric/status?nullifierHash=...
 * Returns whether a voter has a pre-existing biometric profile.
 * If they do, also issues a fresh permanent token so they can skip re-verification.
 */
export async function GET(req) {
  try {
    const { searchParams } = new URL(req.url);
    const nullifierHash = searchParams.get('nullifierHash');

    if (!nullifierHash) {
      return NextResponse.json({ error: 'nullifierHash is required.' }, { status: 400 });
    }

    await connectDB();

    const record = await BiometricHash.findOne({ nullifierHash });

    if (!record) {
      return NextResponse.json({ verified: false, registered: false });
    }

    return NextResponse.json({
      registered: true,
      verified: false, // Enforce face scanning every time they vote
      twinVerificationStatus: record.twinVerificationStatus || 'none',
      bypassDuplicateCheck: record.bypassDuplicateCheck || false,
      verificationCount: record.verificationCount,
      lastVerifiedAt: record.lastVerifiedAt,
      faceAttributes: record.faceAttributes,
    });
  } catch (err) {
    console.error('[biometric/status] Error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import Voter from '@/lib/models/Voter';

export async function POST(req) {
  try {
    const { email, electionId, nullifierHash, notes } = await req.json();

    if (!nullifierHash) {
      return NextResponse.json({ error: 'nullifierHash is required.' }, { status: 400 });
    }

    await connectDB();

    // 1. Verify the voter exists
    const voter = await Voter.findOne({ nullifierHash });
    if (!voter) {
      return NextResponse.json({ error: 'Voter not found.' }, { status: 404 });
    }

    const resolvedElectionId = electionId || voter.electionId || '';

    // 3. Fetch or create the biometric record and set twin status to pending
    let record = await BiometricHash.findOne({ nullifierHash });

    if (!record) {
      record = await BiometricHash.create({
        nullifierHash,
        biometricHash: 'pending-initial-twin-submission',
        faceConfidence: 0.9,
        provider: 'aws-rekognition',
        twinVerificationStatus: 'pending',
        twinNotes: notes?.trim() || 'User submitted twin verification request.',
        registeredAt: new Date(),
        electionId: resolvedElectionId,
      });
    } else {
      record.twinVerificationStatus = 'pending';
      if (notes?.trim()) {
        record.twinNotes = notes.trim();
      } else if (!record.twinNotes) {
        record.twinNotes = 'User requested twin verification override.';
      }
      if (!record.electionId && resolvedElectionId) record.electionId = resolvedElectionId;
      await record.save();
    }

    return NextResponse.json({
      success: true,
      message: 'Twin verification override requested successfully.',
      status: record.twinVerificationStatus,
    });
  } catch (err) {
    console.error('[biometric/twin-request] Error:', err);
    return NextResponse.json({ error: err.message || 'Failed to submit twin request.' }, { status: 500 });
  }
}

/**
 * POST /api/biometric/verify
 *
 * Liveness / human-face gate for mobile voting.
 * Does NOT require a previously enrolled face profile.
 *
 * Checks:
 *  - Exactly one face in frame
 *  - High confidence human face
 *  - Reasonable lighting
 *  - No eyeglasses / sunglasses
 *  - Eyes open (basic live-person signal)
 *
 * On success: issues a short-lived biometric JWT used by verify-otp.
 */
import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import BiometricHash from '@/lib/models/BiometricHash';
import { issueBiometricToken, getRekognitionClient } from '@/lib/biometric';
import { DetectFacesCommand } from '@aws-sdk/client-rekognition';
import { rateLimit } from '@/lib/rateLimit';

const biometricLimiter = rateLimit({
  windowMs: 120_000,
  max: 10,
  keyPrefix: 'biometric-verify',
  message: 'Too many verification attempts. Please wait before trying again.',
});

export async function POST(req) {
  const limited = biometricLimiter(req);
  if (limited) return limited;

  try {
    const { nullifierHash, image, electionId } = await req.json();

    if (!nullifierHash) {
      return NextResponse.json(
        { error: 'nullifierHash is required.' },
        { status: 400 },
      );
    }

    if (!image) {
      return NextResponse.json(
        { error: 'Image (base64 data URL) is required for biometric scan.' },
        { status: 400 },
      );
    }

    await connectDB();

    const rekognition = getRekognitionClient();
    const base64Data = image.replace(/^data:image\/\w+;base64,/, '');
    const liveBuffer = Buffer.from(base64Data, 'base64');

    // ── Detect face(s) ──────────────────────────────────────────────────────
    const detectRes = await rekognition.send(
      new DetectFacesCommand({
        Image: { Bytes: liveBuffer },
        Attributes: ['ALL'],
      }),
    );

    const faces = detectRes.FaceDetails || [];

    if (faces.length === 0) {
      return NextResponse.json(
        {
          success: false,
          error: 'No human face detected. Center your face in the frame and try again.',
        },
        { status: 400 },
      );
    }

    if (faces.length > 1) {
      return NextResponse.json(
        {
          success: false,
          error: 'Multiple faces detected. Only one person should be in the frame.',
        },
        { status: 400 },
      );
    }

    const face = faces[0];

    if ((face.Confidence || 0) < 90) {
      return NextResponse.json(
        {
          success: false,
          error: `Face confidence too low (${Math.round(face.Confidence || 0)}%). Move closer and use better lighting.`,
        },
        { status: 400 },
      );
    }

    if (face.Quality && face.Quality.Brightness < 30) {
      return NextResponse.json(
        {
          success: false,
          error: 'Lighting is too dark. Turn on lights or move to a brighter area.',
        },
        { status: 400 },
      );
    }

    const wearsGlasses =
      (face.Eyeglasses?.Value === true && (face.Eyeglasses?.Confidence || 0) > 80) ||
      (face.Sunglasses?.Value === true && (face.Sunglasses?.Confidence || 0) > 80);

    if (wearsGlasses) {
      return NextResponse.json(
        {
          success: false,
          error: 'Please remove glasses or sunglasses, then try again.',
        },
        { status: 400 },
      );
    }

    // Basic live-person signal: eyes should be open
    if (face.EyesOpen?.Value === false && (face.EyesOpen?.Confidence || 0) > 80) {
      return NextResponse.json(
        {
          success: false,
          error: 'Eyes appear closed. Open your eyes and look at the camera.',
        },
        { status: 400 },
      );
    }

    const faceAttributes = {
      faceConfidence: face.Confidence,
      gender: face.Gender?.Value,
      genderConfidence: face.Gender?.Confidence,
      ageRange: face.AgeRange
        ? `${face.AgeRange.Low} - ${face.AgeRange.High} years old`
        : 'Unknown',
      brightness: face.Quality?.Brightness,
      sharpness: face.Quality?.Sharpness,
      eyesOpen: face.EyesOpen?.Value,
      eyeglasses: face.Eyeglasses?.Value,
      sunglasses: face.Sunglasses?.Value,
    };

    // Soft audit record only — no prior enrollment required
    try {
      await BiometricHash.findOneAndUpdate(
        { nullifierHash },
        {
          $set: {
            lastVerifiedAt: new Date(),
            faceAttributes,
            provider: 'aws-rekognition',
            electionId: electionId ? String(electionId) : '',
          },
          $setOnInsert: {
            nullifierHash,
            biometricHash: `liveness-only-${Date.now()}`,
            faceConfidence: face.Confidence || 0,
            twinVerificationStatus: 'none',
            registeredAt: new Date(),
            verificationCount: 0,
          },
          $inc: { verificationCount: 1 },
        },
        { upsert: true },
      );
    } catch (auditErr) {
      console.warn('[biometric/verify] audit upsert skipped:', auditErr.message);
    }

    const token = issueBiometricToken(nullifierHash);

    return NextResponse.json({
      success: true,
      message: 'Liveness check passed.',
      token,
      faceAttributes,
    });
  } catch (err) {
    console.error('[biometric/verify] Error:', err);

    // Helpful message when AWS is misconfigured / unreachable
    const msg = err?.message || 'Biometric verification failed.';
    if (/credentials|UnrecognizedClient|InvalidClientTokenId|ExpiredToken/i.test(msg)) {
      return NextResponse.json(
        { error: 'Face verification is temporarily unavailable. Please try again later.' },
        { status: 503 },
      );
    }

    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import connectDB from '@/lib/db';
import Candidate from '@/lib/models/Candidate';

// GET /api/candidates?electionId=0
export async function GET(request) {
  try {
    await connectDB();
    const { searchParams } = new URL(request.url);
    if (!searchParams.has('electionId'))
      return NextResponse.json(
        { success: false, error: 'electionId query param is required' },
        { status: 400 }
      );

    const candidates = await Candidate.find({
      electionId: searchParams.get('electionId'),
    })
      .sort({ candidateId: 1 })
      .lean();

    return NextResponse.json({ success: true, count: candidates.length, data: candidates });
  } catch (err) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

// POST /api/candidates  — called by event listener (CandidateAdded)
export async function POST(request) {
  try {
    await connectDB();
    const { electionId, candidateId, name, party, symbol, manifesto, txHash, blockNumber } =
      await request.json();

    const candidate = await Candidate.findOneAndUpdate(
      { electionId: String(electionId), candidateId: Number(candidateId) },
      { electionId: String(electionId), candidateId: Number(candidateId), name, party, symbol, manifesto, txHash, blockNumber },
      { upsert: true, returnDocument: 'after' }
    );

    return NextResponse.json({ success: true, data: candidate }, { status: 201 });
  } catch (err) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

// PATCH /api/candidates  — increment voteCount (called by VoteCast event listener)
export async function PATCH(request) {
  try {
    await connectDB();
    const { electionId, candidateId } = await request.json();

    const candidate = await Candidate.findOneAndUpdate(
      { electionId: String(electionId), candidateId: Number(candidateId) },
      { $inc: { voteCount: 1 } },
      { returnDocument: 'after' }
    );

    if (!candidate)
      return NextResponse.json({ success: false, error: 'Candidate not found' }, { status: 404 });

    return NextResponse.json({ success: true, data: candidate });
  } catch (err) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

