export async function GET() {
  try {
    await connectDB();

    const dbElections = await Election.find({
      phase: 1,
      guardianApproved: true,
    })
      .sort({ createdAt: -1 })
      .lean();

    let onChain = [];
    try {
      const contract = await getReadContract();
      const raw = await contract.getAllElections();
      onChain = raw.map((e) => ({
        id: e.id,
        title: e.title,
