/**
 * GET    /api/relay/transactions — relay gas history and analytics
 * DELETE /api/relay/transactions — clear history (guardian only)
 */
import { NextResponse } from 'next/server';
import { ethers } from 'ethers';
import connectDB from '@/lib/db';
import RelayTransaction from '@/lib/models/RelayTransaction';
import { getRelayBalance, getRelayAddress } from '@/lib/relay';

async function isGuardianAddress(address) {
  if (!address || !ethers.isAddress(address)) return false;
  const normalized = address.toLowerCase();
  const envGuardians = [
    process.env.ADMIN_RELAY_ADDRESS,
    process.env.GUARDIAN_1_ADDRESS,
    process.env.GUARDIAN_2_ADDRESS,
    process.env.GUARDIAN_3_ADDRESS,
  ]
    .filter(Boolean)
    .map((a) => a.toLowerCase());
  if (envGuardians.includes(normalized)) return true;

  try {
    const contractAddress = process.env.NEXT_PUBLIC_CONTRACT_ADDRESS;
    if (!contractAddress) return false;
    const abi = (await import('@/lib/contracts/VotingV1.json')).default.abi;
    const provider = new ethers.JsonRpcProvider(
      process.env.RPC_URL || process.env.NEXT_PUBLIC_RPC_URL,
    );
    const contract = new ethers.Contract(contractAddress, abi, provider);
    const onChain = await contract.getGuardians();
    return onChain.some((g) => g.toLowerCase() === normalized);
  } catch {
    return false;
  }
}

export async function GET(req) {
  try {
    await connectDB();

    const { searchParams } = new URL(req.url);
    const limit = Math.min(Number(searchParams.get('limit')) || 50, 200);
    const page = Math.max(Number(searchParams.get('page')) || 1, 1);
    const op = searchParams.get('op');

    const filter = op ? { operation: op } : {};
    const skip = (page - 1) * limit;

    const [transactions, total, byOperation, dailySpend, address, balance] = await Promise.all([
      RelayTransaction.find(filter)
        .sort({ timestamp: -1 })
        .skip(skip)
        .limit(limit)
        .lean(),
      RelayTransaction.countDocuments(filter),
      RelayTransaction.aggregate([
        {
          $group: {
            _id: '$operation',
            count: { $sum: 1 },
            totalGasEth: { $sum: { $toDouble: '$gasCostEth' } },
          },
        },
        { $sort: { totalGasEth: -1 } },
      ]),
      RelayTransaction.aggregate([
        {
          $match: {
            timestamp: { $gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) },
          },
        },
        {
          $group: {
            _id: { $dateToString: { format: '%Y-%m-%d', date: '$timestamp' } },
            count: { $sum: 1 },
            gasEth: { $sum: { $toDouble: '$gasCostEth' } },
          },
        },
        { $sort: { _id: 1 } },
      ]),
      getRelayAddress(),
      getRelayBalance(),
    ]);

    const allTimeAgg = await RelayTransaction.aggregate([
      {
        $group: {
          _id: null,
          totalGasEth: { $sum: { $toDouble: '$gasCostEth' } },
          totalTx: { $sum: 1 },
          avgGasEth: { $avg: { $toDouble: '$gasCostEth' } },
        },
      },
    ]);
    const allTime = allTimeAgg[0] || { totalGasEth: 0, totalTx: 0, avgGasEth: 0 };

    const last24hAgg = await RelayTransaction.aggregate([
      { $match: { timestamp: { $gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } },
      {
        $group: {
          _id: null,
          totalGasEth: { $sum: { $toDouble: '$gasCostEth' } },
          count: { $sum: 1 },
        },
      },
    ]);
    const last24h = last24hAgg[0] || { totalGasEth: 0, count: 0 };

    return NextResponse.json({
      address,
      balance,
      pagination: { page, limit, total, pages: Math.ceil(total / limit) },
      analytics: {
        totalGasSpentEth: Number(allTime.totalGasEth.toFixed(8)),
        totalTransactions: allTime.totalTx,
        avgGasPerTxEth: Number((allTime.avgGasEth || 0).toFixed(8)),
        last24hGasEth: Number(last24h.totalGasEth.toFixed(8)),
        last24hTxCount: last24h.count,
        byOperation: byOperation.map((r) => ({
          operation: r._id,
          count: r.count,
          totalGasEth: Number(r.totalGasEth.toFixed(8)),
        })),
        dailySpend: dailySpend.map((d) => ({
          date: d._id,
          count: d.count,
          gasEth: Number(d.gasEth.toFixed(8)),
        })),
      },
      transactions: transactions.map((t) => ({
        txHash: t.txHash,
        blockNumber: t.blockNumber,
        operation: t.operation,
        electionId: t.electionId,
        orgSlug: t.orgSlug,
        gasUsed: t.gasUsed,
        gasPrice: t.gasPrice,
        gasCostEth: t.gasCostEth,
        timestamp: t.timestamp,
        metadata: t.metadata,
      })),
    });
  } catch (err) {
    console.error('[relay/transactions]', err);
    return NextResponse.json({ error: err.message || 'Failed to load relay transactions' }, { status: 500 });
  }
}

/** Clear relay transaction log (MongoDB only — on-chain txs are unchanged). */
export async function DELETE(req) {
  try {
    const body = await req.json().catch(() => ({}));
    const { guardianAddress, before, scope } = body;

    if (!(await isGuardianAddress(guardianAddress))) {
      return NextResponse.json(
        { error: 'Unauthorized — connect with a registered guardian wallet' },
        { status: 403 },
      );
    }

    await connectDB();

    let filter = {};
    if (scope === 'before' && before) {
      const cutoff = new Date(before);
      if (Number.isNaN(cutoff.getTime())) {
        return NextResponse.json({ error: 'Invalid before date' }, { status: 400 });
      }
      filter = { timestamp: { $lt: cutoff } };
    }

    const result = await RelayTransaction.deleteMany(filter);

    return NextResponse.json({
      success: true,
      deleted: result.deletedCount,
      message:
        result.deletedCount === 0
          ? 'No transactions matched — history is already empty'
          : `Cleared ${result.deletedCount} transaction record(s)`,
    });
  } catch (err) {
    console.error('[relay/transactions DELETE]', err);
    return NextResponse.json(
      { error: err.message || 'Failed to clear transaction history' },
      { status: 500 },
    );
  }
}

/**
 * POST /api/relay/vote
 * Standalone gasless vote casting endpoint.
 *
 * This is the dedicated relay route for vote submission.
 * The full voter auth flow (OTP verification → cast vote) is handled by
 * /api/auth/verify-otp — that route calls relayCastVote() internally.
 *
 * This standalone endpoint is useful for:
 *   - Direct integrations (mobile apps, kiosks)
 *   - Admin-initiated test votes
 *   - Future wallet-based voting flows
 *
 * Body: { electionId, candidateId, nullifierHash }
 *
 * Security:
 *   - Requires a pre-validated server-issued vote token (JWT) in Authorization header
 *   - OR an x-relay-api-key matching ADMIN_API_KEY for server-to-server calls
 *   - The nullifierHash must already be registered on-chain via bulk-register
 *   - Double-vote prevention is enforced by the smart contract (reverts if already voted)
 */
import { NextResponse } from "next/server";
import { ethers } from "ethers";
import connectDB from "@/lib/db";
import Voter from "@/lib/models/Voter";
import Election from "@/lib/models/Election";
import { relayCastVote } from "@/lib/relay";
import { preflightCheck } from "@/lib/preflightCache";

export async function POST(req) {
  try {
    const body = await req.json();
    const { electionId, candidateId, nullifierHash } = body;

    // ── Input validation ──────────────────────────────────────────────────────
    if (electionId === undefined || electionId === null || electionId === "") {
      return NextResponse.json(
        { error: "electionId is required" },
        { status: 400 },
      );
    }
    if (
      candidateId === undefined ||
      candidateId === null ||
      candidateId === ""
    ) {
      return NextResponse.json(
        { error: "candidateId is required" },
        { status: 400 },
      );
    }
    if (
      !nullifierHash ||
      !nullifierHash.startsWith("0x") ||
      nullifierHash.length !== 66
    ) {
      return NextResponse.json(
        {
          error:
            "nullifierHash must be a valid 32-byte hex string (0x-prefixed)",
        },
        { status: 400 },
      );
    }

    const eid = String(electionId);
    const cid = Number(candidateId);

    if (isNaN(cid)) {
      return NextResponse.json(
        { error: "candidateId must be a number" },
        { status: 400 },
      );
    }

    await connectDB();

    // ── Election must be in Voting phase and guardian-approved ────────────────
    const election = await Election.findOne({ electionId: eid }).lean();
    if (!election) {
      return NextResponse.json(
        { error: "Election not found" },
        { status: 404 },
      );
    }
    if (election.phase !== 1) {
      return NextResponse.json(
        {
          error:
            election.phase === 0
              ? "Election is still in registration phase — voting has not started"
              : "Election has already ended",
        },
        { status: 403 },
      );
    }
    if (!election.guardianApproved) {
      return NextResponse.json(
        { error: "Election has not been approved by a guardian yet" },
        { status: 403 },
      );
    }

    // ── Verify the nullifier belongs to a registered voter in this election ───
    const voter = await Voter.findOne({
      nullifierHash,
      electionId: eid,
    }).lean();
    if (!voter) {
      return NextResponse.json(
        { error: "Voter is not registered for this election" },
        { status: 403 },
      );
    }
    if (voter.status !== "registered") {
      return NextResponse.json(
        {
          error: `Voter registration status is "${voter.status}" — must be "registered" to vote`,
        },
        { status: 403 },
      );
    }

    // ── Edge pre-flight: cache-backed double-vote guard (faster than chain read) ─
    const preflight = await preflightCheck(nullifierHash, eid);
    if (!preflight.allowed) {
      return NextResponse.json({ error: preflight.reason }, { status: 403 });
    }

    // ── Cast vote on-chain via relay ──────────────────────────────────────────
    // PRIVACY: Do NOT pass voter location — GPS coordinates alongside vote
    // data create a metadata channel that can identify voters.
    const { txHash, blockNumber } = await relayCastVote(
      eid,
      cid,
      nullifierHash,
    );

    return NextResponse.json({
      success: true,
      message: "Vote successfully relayed and recorded on the blockchain.",
      txHash,
      blockNumber,
      electionId: eid,
    });
  } catch (err) {
    console.error("[relay/vote]", err);

    // Friendly messages for common contract reverts
    const msg = err.message || "";
    if (msg.includes("already voted")) {
      return NextResponse.json(
        { error: "This voter has already cast a vote in this election." },
        { status: 409 },
      );
    }
    if (msg.includes("voter not registered")) {
      return NextResponse.json(
        { error: "Voter nullifier is not registered on-chain." },
        { status: 403 },
      );
    }
    if (msg.includes("not voting phase")) {
      return NextResponse.json(
        { error: "Election is not in the voting phase." },
        { status: 403 },
      );
    }
    if (msg.includes("invalid candidate")) {
      return NextResponse.json(
        { error: "Invalid candidate ID for this election." },
        { status: 400 },
      );
    }

    return NextResponse.json(
      { error: err.message || "Vote relay failed" },
      { status: 500 },
    );
  }
}

