    fetch(`/api/org/${slug}/elections/${electionId}/results`)
      .then((r) => r.json())
      .then((d) => {
        if (!d.success && d.error) throw new Error(d.error);
        setData(d);
      })
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, [slug, electionId]);

  if (loading) {
    return (
      <div className="flex justify-center py-12">
