          const isWinner = winner && c.id === winner.id;

          return (
            <div
              key={c.id}
              className={`relative overflow-hidden rounded-xl border p-4 transition-all ${
                isWinner
                  ? 'bg-canvas border-accent-yellow/40 shadow-sm'
