 * Returns null if credentials are not configured.
 */
export function getRekognitionClient() {
  const region = process.env.AWS_REGION || "us-east-1";

  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
