/**
 * lib/db.js
 * MongoDB singleton for Next.js.
 *
 * Next.js runs API Route Handlers in a serverless-like environment where the
 * module is re-evaluated on cold-starts. A global cached promise prevents
 * opening a new connection on every request during development (HMR) and in a
 * multi-instance serverless production deployment.
 */
import mongoose from 'mongoose';

const MONGODB_URI = process.env.MONGODB_URI;

if (!MONGODB_URI) {
  throw new Error(
    'Please define MONGODB_URI in your .env.local file.\n' +
    'Example: MONGODB_URI=mongodb+srv://<user>:<pass>@cluster.mongodb.net/votingdapp'
  );
}

// Use a global variable so the connection is reused across hot-reloads in dev.
let cached = global._mongoose;
if (!cached) {
  cached = global._mongoose = { conn: null, promise: null };
}

async function connectDB() {
  if (cached.conn) return cached.conn;

  if (!cached.promise) {
    cached.promise = mongoose.connect(MONGODB_URI, {
      dbName: 'votingdapp',
      bufferCommands: false,
    });
  }

  cached.conn = await cached.promise;
  return cached.conn;
}

export default connectDB;

/**
 * lib/ipfs.js
 * Pinata IPFS utility — pin JSON and files to IPFS via Pinata API.
 *
 * Usage:
 *   import { pinJSON, pinFile, getIPFSUrl } from '@/lib/ipfs';
 *
 *   const cid = await pinJSON({ type: 'voter-list', data: [...] }, 'voter-list-election-0');
 *   const url = getIPFSUrl(cid);
 */

const PINATA_JWT = process.env.PINATA_JWT;
const PINATA_API_KEY = process.env.PINATA_API_KEY;
const PINATA_API_SECRET = process.env.PINATA_API_SECRET;
const PINATA_GATEWAY =
  process.env.PINATA_GATEWAY || "https://gateway.pinata.cloud/ipfs";

if (!PINATA_JWT) {
  console.warn("[ipfs] PINATA_JWT not set — IPFS pinning will fail at runtime");
}

/**
 * Pin a JSON object to IPFS via Pinata.
 * Returns the IPFS CID (content identifier) string.
 *
 * @param {object} jsonData  — the object to pin
 * @param {string} name      — human-readable name shown in Pinata dashboard
 * @param {object} metadata  — optional key/value metadata attached to the pin
 * @returns {Promise<string>} CID
 */
export async function pinJSON(
  jsonData,
  name = "block-vote-data",
  metadata = {},
) {
  const body = {
    pinataContent: jsonData,
    pinataMetadata: { name, keyvalues: metadata },
    pinataOptions: { cidVersion: 1 },
  };

  const res = await fetch("https://api.pinata.cloud/pinning/pinJSONToIPFS", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${PINATA_JWT}`,
    },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Pinata pinJSON failed (${res.status}): ${err}`);
  }

  const data = await res.json();
  return data.IpfsHash; // CID
}

/**
 * Pin a file (Buffer or Blob) to IPFS via Pinata.
 * Returns the IPFS CID.
 *
 * @param {Buffer|Blob} fileBuffer — raw file bytes
 * @param {string} fileName        — filename for the pin
 * @param {string} mimeType        — MIME type of the file
 * @param {object} metadata        — optional key/value metadata
 * @returns {Promise<string>} CID
 */
export async function pinFile(
  fileBuffer,
  fileName,
  mimeType = "application/octet-stream",
  metadata = {},
) {
  const formData = new FormData();

  const blob =
    fileBuffer instanceof Blob
      ? fileBuffer
      : new Blob([fileBuffer], { type: mimeType });

  formData.append("file", blob, fileName);
  formData.append(
    "pinataMetadata",
    JSON.stringify({ name: fileName, keyvalues: metadata }),
  );
  formData.append("pinataOptions", JSON.stringify({ cidVersion: 1 }));

  const res = await fetch("https://api.pinata.cloud/pinning/pinFileToIPFS", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${PINATA_JWT}`,
    },
    body: formData,
  });

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Pinata pinFile failed (${res.status}): ${err}`);
  }

  const data = await res.json();
  return data.IpfsHash; // CID
}

/**
 * Fetch and return the JSON content of an IPFS CID.
 * Uses the Pinata gateway by default.
 *
 * @param {string} cid
 * @returns {Promise<object>}
 */
export async function fetchFromIPFS(cid) {
  const url = `${PINATA_GATEWAY}/${cid}`;
  const res = await fetch(url);
  if (!res.ok)
    throw new Error(`IPFS fetch failed for CID ${cid}: ${res.status}`);
  return res.json();
}

/**
 * Returns a publicly accessible IPFS gateway URL for a given CID.
 *
 * @param {string} cid
 * @returns {string}
 */
export function getIPFSUrl(cid) {
  if (!cid) return "";
  return `${PINATA_GATEWAY}/${cid}`;
}

/**
 * Unpin a CID from Pinata (frees storage quota).
 *
 * @param {string} cid
 * @returns {Promise<void>}
 */
export async function unpin(cid) {
  const res = await fetch(`https://api.pinata.cloud/pinning/unpin/${cid}`, {
    method: "DELETE",
    headers: { Authorization: `Bearer ${PINATA_JWT}` },
  });
  if (!res.ok) {
    const err = await res.text();
    console.warn(`[ipfs] unpin failed for ${cid}: ${err}`);
  }
}

/**
 * lib/mailer.js
 * Email sender using Resend HTTP API (port 443 — works on any network).
 * Set RESEND_API_KEY and RESEND_FROM in .env
 * Fallback: set DEV_SKIP_EMAIL=true to print OTP to terminal without sending.
 */
import { Resend } from 'resend';

let _resend = null;
let _resendKey = null;

/** Resend blocks placeholder domains like example.com — see resend.com/docs/dashboard/emails/testing */
const BLOCKED_RECIPIENT_DOMAINS = new Set([
  'example.com',
  'example.org',
  'example.net',
  'test.com',
]);

function isBlockedTestRecipient(email) {
  const domain = String(email).split('@')[1]?.toLowerCase();
  return BLOCKED_RECIPIENT_DOMAINS.has(domain);
}

export function getResendClient() {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    throw new Error('RESEND_API_KEY is not set');
  }
  if (_resend && _resendKey === apiKey) return _resend;
  _resendKey = apiKey;
  _resend = new Resend(apiKey);
  return _resend;
}

function getFromAddress() {
  return process.env.RESEND_FROM || 'Block Vote <onboarding@resend.dev>';
}

function resolveRecipient(to) {
  if (isBlockedTestRecipient(to)) {
    const msg = `Invalid recipient ${to}: Resend blocks placeholder domains like example.com. Use a real email or a Resend test address (delivered@resend.dev).`;
    if (process.env.NODE_ENV === 'development') {
      console.warn(`[mailer] ${msg}`);
      return null;
    }
    throw new Error(msg);
  }
  return process.env.RESEND_DEV_REDIRECT || to;
}

async function sendEmail({ to, subject, html, text, logLabel = 'email' }) {
  const actualTo = resolveRecipient(to);
  if (!actualTo) return { skipped: true };

  const from = getFromAddress();
  const actualSubject = process.env.RESEND_DEV_REDIRECT && actualTo !== to
    ? `[→ ${to}] ${subject}`
    : subject;

  const { data, error } = await getResendClient().emails.send({
    from,
    to: actualTo,
    subject: actualSubject,
    html,
    text,
  });

  if (error) {
    const keyHint = process.env.RESEND_API_KEY?.slice(0, 8) ?? 'missing';
    throw new Error(`${error.message} (from=${from}, key=${keyHint}...)`);
  }

  if (process.env.RESEND_DEV_REDIRECT && actualTo !== to) {
    console.log(`[mailer] ${logLabel} for ${to} redirected to ${actualTo} (RESEND_DEV_REDIRECT)`);
  }

  return { id: data?.id };
}

export function getTransporter() {
  return getResendClient();
}

