/**
 * lib/preflightCache.js
 * Edge Pre-flight Validation Cache
 * 
 * Simulates edge-computing behavior (Lambda@Edge + DynamoDB Global Tables)
 * using MongoDB as the fast lookup cache. In production, this would be
 * deployed to CloudFront Lambda@Edge with DynamoDB for sub-10ms latency.
 * 
 * Purpose: Reject invalid/duplicate votes BEFORE they hit the blockchain,
 * saving gas fees and reducing network congestion.
 */
import connectDB from '@/lib/db';
import Voter from '@/lib/models/Voter';
import Election from '@/lib/models/Election';

/**
 * Pre-flight validation for a vote attempt.
 * Returns { allowed: boolean, reason: string, latencyMs: number, isRevote?: boolean }
 * 
 * Checks performed (all from MongoDB cache — no blockchain query):
 * 1. Is the voter registered on-chain for this specific election?
 * 2. Has the voter already voted? (V3: allowed as re-vote, V1: blocked)
 * 3. Is the election in the Voting phase?
 *
 * electionId is a string (bytes32 hex from the smart contract)
 */
export async function preflightCheck(nullifierHash, electionId) {
  const start = Date.now();

  await connectDB();

  // Check 1: Is the voter registered for this election?
  const voter = await Voter.findOne(
    { nullifierHash, electionId: String(electionId), status: 'registered' },
    { _id: 1, hasVoted: 1 }
  ).lean();

  if (!voter) {
    return {
      allowed: false,
      reason: 'Voter not registered. Registration is required before voting.',
      code: 'NOT_REGISTERED',
      latencyMs: Date.now() - start,
      cached: true,
    };
  }

  // Check 2: Has the voter already voted?
  // With V3 re-voting, we ALLOW re-votes — the smart contract handles the
  // decrement/increment logic. We flag isRevote so the UI can inform the voter.
  const isRevote = voter.hasVoted === true;

  // Check 3: Is the election in the Voting phase?
  const election = await Election.findOne(
    { electionId: String(electionId) },
    { phase: 1 }
  ).lean();

  if (!election) {
    return {
      allowed: false,
      reason: 'Election not found.',
      code: 'ELECTION_NOT_FOUND',
      latencyMs: Date.now() - start,
      cached: true,
    };
  }

  if (election.phase !== 1) {
    const phaseNames = ['Registration', 'Voting', 'Completed'];
    return {
      allowed: false,
      reason: `Election is in "${phaseNames[election.phase]}" phase, not "Voting".`,
      code: 'WRONG_PHASE',
      latencyMs: Date.now() - start,
      cached: true,
    };
  }

  // All checks passed
  return {
    allowed: true,
    reason: isRevote
      ? 'Re-vote allowed. Your previous vote will be replaced.'
      : 'Pre-flight validation passed. Vote is eligible.',
    code: isRevote ? 'REVOTE_ALLOWED' : 'ALLOWED',
    isRevote,
    latencyMs: Date.now() - start,
    cached: true,
  };
}

/**
 * lib/rateLimit.js
 * In-memory sliding-window rate limiter for API routes.
 *
 * PRIVACY NOTE:
 *   This rate limiter uses IP addresses for throttling, but the IP is never
 *   stored alongside vote data. Rate limiting happens BEFORE any vote
 *   processing, and the IP is discarded after the window expires.
 *
 * Usage:
 *   import { rateLimit } from '@/lib/rateLimit';
 *
 *   const limiter = rateLimit({ windowMs: 60_000, max: 5 });
 *
 *   export async function POST(req) {
 *     const limited = limiter(req);
 *     if (limited) return limited; // Returns 429 response
 *     // ... handle request
 *   }
 */

import { NextResponse } from 'next/server';

const stores = new Map();

/**
 * Creates a rate limiter middleware function.
 *
 * @param {object} options
 * @param {number} options.windowMs  — Time window in milliseconds (default: 60s)
 * @param {number} options.max       — Max requests per window per key (default: 10)
 * @param {string} options.message   — Error message for 429 responses
 * @param {string} options.keyPrefix — Prefix to isolate limiter instances
 * @returns {function} — Call with (req) → null if allowed, NextResponse if blocked
 */
export function rateLimit({
  windowMs = 60_000,
  max = 10,
  message = 'Too many requests. Please try again later.',
  keyPrefix = 'rl',
} = {}) {
  // Each limiter instance gets its own store
  const storeKey = `${keyPrefix}_${windowMs}_${max}`;
  if (!stores.has(storeKey)) {
    stores.set(storeKey, new Map());
  }
  const store = stores.get(storeKey);

  // Periodic cleanup of expired entries (every 5 minutes)
  let lastCleanup = Date.now();
  const CLEANUP_INTERVAL = 5 * 60 * 1000;

  return function check(req) {
    const now = Date.now();

    // Cleanup stale entries periodically
    if (now - lastCleanup > CLEANUP_INTERVAL) {
      lastCleanup = now;
      for (const [key, entry] of store) {
        // Remove entries where all timestamps are outside the window
        entry.timestamps = entry.timestamps.filter(t => now - t < windowMs);
        if (entry.timestamps.length === 0) store.delete(key);
      }
    }

    // Extract client identifier — use forwarded IP or fallback
    const forwarded = req.headers.get('x-forwarded-for');
    const ip = forwarded ? forwarded.split(',')[0].trim() : 'unknown';
    const key = `${keyPrefix}:${ip}`;

    // Get or create entry
    if (!store.has(key)) {
      store.set(key, { timestamps: [] });
    }
    const entry = store.get(key);

    // Remove timestamps outside the current window
    entry.timestamps = entry.timestamps.filter(t => now - t < windowMs);

    // Check if over limit
    if (entry.timestamps.length >= max) {
      const retryAfterMs = windowMs - (now - entry.timestamps[0]);
      const retryAfterSec = Math.ceil(retryAfterMs / 1000);

      return NextResponse.json(
        { error: message },
        {
          status: 429,
          headers: {
            'Retry-After': String(retryAfterSec),
            'X-RateLimit-Limit': String(max),
            'X-RateLimit-Remaining': '0',
            'X-RateLimit-Reset': String(Math.ceil((now + retryAfterMs) / 1000)),
          },
        },
      );
    }

    // Record this request
    entry.timestamps.push(now);
    return null; // Allowed
  };
}

/**
 * lib/relay.js
 * Platform gas-station relay — submits all blockchain transactions on behalf of voters.
 * The relay wallet pays ALL gas. Voters have zero blockchain interaction.
 */
import { ethers } from 'ethers';
import { createRequire } from 'module';
const require = createRequire(import.meta.url);

let _provider = null;
let _relayWallet = null;
let _contract = null;
let _relayQueue = Promise.resolve();

function isNonceError(err) {
  const msg = err?.message || err?.info?.error?.message || '';
  return (
    err?.code === 'NONCE_EXPIRED' ||
    msg.includes('nonce too low') ||
    msg.includes('Nonce too low') ||
    msg.includes('nonce has already been used')
  );
}

/** Serialize relay txs — only one in-flight at a time to avoid nonce collisions. */
function enqueueRelay(task) {
  const run = _relayQueue.then(task, task);
  _relayQueue = run.catch(() => {});
  return run;
}

async function sendRelayTx(sendFn, maxAttempts = 4) {
  return enqueueRelay(async () => {
    let lastErr;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      resetRelayNonce();
      try {
        const tx = await sendFn();
        return await tx.wait();
      } catch (err) {
        lastErr = err;
        if (isNonceError(err) && attempt < maxAttempts - 1) {
          console.warn(`[relay] nonce sync retry ${attempt + 1}/${maxAttempts - 1}`);
          await new Promise((r) => setTimeout(r, 800 * (attempt + 1)));
          continue;
        }
        throw err;
      }
    }
    throw lastErr;
  });
}

function getProvider() {
  if (!_provider) {
    _provider = new ethers.JsonRpcProvider(process.env.RPC_URL || 'http://127.0.0.1:8545');
  }
  return _provider;
}

function getRelayWallet() {
  if (!_relayWallet) {
    const key = process.env.ADMIN_RELAY_PRIVATE_KEY;
    if (!key) throw new Error('ADMIN_RELAY_PRIVATE_KEY not set in .env');
    const baseWallet = new ethers.Wallet(key, getProvider());
    // Wrap with NonceManager to safely handle rapid sequential transactions (like bulk register)
    _relayWallet = new ethers.NonceManager(baseWallet);
  }
  return _relayWallet;
}

function getContract() {
  if (!_contract) {
    const abi = require('./contracts/VotingV3.json').abi;
    const address = process.env.NEXT_PUBLIC_CONTRACT_ADDRESS;
    if (!address) throw new Error('NEXT_PUBLIC_CONTRACT_ADDRESS not set in .env');
    _contract = new ethers.Contract(address, abi, getRelayWallet());
  }
  return _contract;
}

// ─── Relay Operations ─────────────────────────────────────────────────────────

/** Log relay gas spend to MongoDB for Guardian analytics */
async function logRelayTransaction(receipt, operation, extra = {}) {
  try {
    const connectDB = (await import('./db.js')).default;
    const RelayTransaction = (await import('./models/RelayTransaction.js')).default;
    await connectDB();

    const gasUsed = receipt.gasUsed ?? 0n;
    const gasPrice = receipt.gasPrice ?? 0n;
    const gasCostWei = gasUsed * gasPrice;

    await RelayTransaction.findOneAndUpdate(
      { txHash: receipt.hash },
      {
        txHash: receipt.hash,
        blockNumber: receipt.blockNumber,
        operation,
        gasUsed: gasUsed.toString(),
        gasPrice: gasPrice.toString(),
        gasCostEth: ethers.formatEther(gasCostWei),
        timestamp: new Date(),
        ...extra,
      },
      { upsert: true, returnDocument: 'after' },
    );
  } catch (dbErr) {
    console.error('Failed to log relay transaction:', dbErr);
  }
}

/** Reset the NonceManager — call before bulk operations to re-sync from chain */
export function resetRelayNonce() {
  if (_relayWallet) _relayWallet.reset();
}

/** Register a voter on-chain for a specific election by their nullifier hash */
export async function relayRegisterVoter(electionId, nullifierHash, metadata = {}) {
  const receipt = await sendRelayTx(() =>
    getContract().registerVoterByRelay(electionId, nullifierHash),
  );
  await logRelayTransaction(receipt, 'register_voter', { electionId, metadata });
  return { txHash: receipt.hash, blockNumber: receipt.blockNumber };
}

/** Cast a vote on behalf of a voter (after OTP verification) */
export async function relayCastVote(electionId, candidateId, voterNullifier) {
  // Random ballot salt blinds the on-chain VoteCastPrivate event
  const ballotSalt = ethers.hexlify(ethers.randomBytes(32));

  let isRevote = false;

  // Check if this is a re-vote (VotingV3 supports changing your vote)
  try {
    const [voted] = await getContract().getVoteStatus(voterNullifier, electionId);
    isRevote = voted;
  } catch {
    // Should not happen with VotingV3 — log but don't fail
    console.warn('[relay] getVoteStatus failed — treating as first vote');
  }

  const receipt = await sendRelayTx(() =>
    getContract().castVoteRelayedV3(electionId, candidateId, voterNullifier, ballotSalt),
  );

  const usedV3 = true;

  await logRelayTransaction(receipt, isRevote ? 'revote' : 'cast_vote', { electionId });

  // Log the vote to MongoDB for analytics and fast preflight checks.
  // PRIVACY: Do NOT store voterNullifier or voterLocation here.
  try {
    const connectDB = (await import('./db.js')).default;
    const VoteActivity = (await import('./models/VoteActivity.js')).default;
    const Election = (await import('./models/Election.js')).default;
    await connectDB();

    // Each transaction (including re-votes) gets its own VoteActivity record
    await VoteActivity.findOneAndUpdate(
      { txHash: receipt.hash },
      {
        electionId,
        candidateId: Number(candidateId),
        txHash: receipt.hash,
        blockNumber: receipt.blockNumber,
        timestamp: new Date(),
        isRevote,
        // Store ballotHash for audit (can verify vote integrity without revealing voter)
        ...(usedV3 ? { ballotHash: ethers.keccak256(
          ethers.solidityPacked(
            ['bytes32', 'uint256', 'bytes32', 'bytes32'],
            [electionId, candidateId, voterNullifier, ballotSalt]
          )
        )} : {}),
      },
      { upsert: true, returnDocument: 'after' }
    );

    // Only increment totalVotes on FIRST vote (not re-votes)
    if (!isRevote) {
      await Election.findOneAndUpdate(
        { electionId },
        { $inc: { totalVotes: 1 } }
      );
    }
  } catch (dbErr) {
    console.error('Failed to log vote activity in MongoDB:', dbErr);
  }

  return { txHash: receipt.hash, blockNumber: receipt.blockNumber, isRevote };
}

/** Create an election via relay (admin only) — returns bytes32 election ID */
export async function relayCreateElection(title, description, bannerUrl, startTime, endTime, orgSlug) {
  const receipt = await sendRelayTx(() =>
    getContract().createElection(title, description, bannerUrl, startTime, endTime),
  );
  await logRelayTransaction(receipt, 'create_election', { orgSlug });

  // Parse the ElectionCreated event to get the bytes32 election ID
  let electionId = null;
  try {
    const abi = require('./contracts/VotingV1.json').abi;
    const iface = new ethers.Interface(abi);
    for (const log of receipt.logs) {
      try {
        const parsed = iface.parseLog({ topics: log.topics, data: log.data });
        if (parsed && parsed.name === 'ElectionCreated') {
          electionId = parsed.args[0]; // bytes32 electionId (first indexed param)
          break;
        }
      } catch {
        // Not our event, skip
      }
    }
  } catch (parseErr) {
    console.warn('[relay] Could not parse ElectionCreated event:', parseErr.message);
  }

  return { txHash: receipt.hash, blockNumber: receipt.blockNumber, electionId };
}

/** Add a candidate via relay */
export async function relayAddCandidate(electionId, name, party, symbol, manifesto, photoUrl, orgSlug) {
  const receipt = await sendRelayTx(() =>
    getContract().addCandidate(electionId, name, party, symbol, manifesto, photoUrl),
  );
  await logRelayTransaction(receipt, 'add_candidate', { electionId, orgSlug });
  return { txHash: receipt.hash, blockNumber: receipt.blockNumber };
}

/** Transition election phase via relay */
export async function relayTransitionPhase(electionId, newPhase, orgSlug) {
  const receipt = await sendRelayTx(() =>
    getContract().transitionPhase(electionId, newPhase),
  );
  await logRelayTransaction(receipt, 'transition_phase', {
    electionId,
    orgSlug,
    metadata: { newPhase: Number(newPhase) },
  });
  return { txHash: receipt.hash, blockNumber: receipt.blockNumber };
}

