/**
 * AWS S3 helpers for party symbol and candidate image uploads.
 */
import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
import { randomUUID } from 'crypto';
import {
  buildAssetProxyPath,
  isPublicAssetKey,
} from '@/lib/urlUtils';

let _client = null;

function getS3Client() {
  if (!_client) {
    const region = process.env.AWS_REGION || process.env.AWS_S3_REGION;
    if (!region) {
      throw new Error('AWS_REGION (or AWS_S3_REGION) is not configured.');
    }
    _client = new S3Client({
      region,
      credentials:
        process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY
          ? {
              accessKeyId: process.env.AWS_ACCESS_KEY_ID,
              secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
            }
          : undefined,
    });
  }
  return _client;
}

function getBucket() {
  const bucket = process.env.AWS_S3_BUCKET;
  if (!bucket) throw new Error('AWS_S3_BUCKET is not configured.');
  return bucket;
}

/** Build a public HTTPS URL to the app asset proxy (for on-chain storage). */
export function buildAssetProxyUrl(key, origin) {
  const path = buildAssetProxyPath(key);
  const base = (origin || process.env.NEXTAUTH_URL || '').replace(/\/$/, '');
  return base ? `${base}${path}` : path;
}

/**
 * Fetch an object from S3 (used by the public asset proxy).
 * @param {string} key
 */
export async function getObjectFromS3(key) {
  if (!isPublicAssetKey(key)) {
    throw new Error('Asset path not allowed');
  }

  const response = await getS3Client().send(
    new GetObjectCommand({
      Bucket: getBucket(),
      Key: key,
    }),
  );

  if (!response.Body) {
    throw new Error('Empty object body');
  }

  return {
    body: response.Body,
    contentType: response.ContentType || 'application/octet-stream',
    cacheControl: response.CacheControl || 'public, max-age=31536000, immutable',
  };
}

const EXT_BY_TYPE = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'image/svg+xml': 'svg',
};

/**
 * Upload a buffer to S3 and return the proxy URL (no public bucket required).
 * @param {{ buffer: Buffer, contentType: string, folder?: string, fileName?: string, origin?: string }} opts
 */
export async function uploadToS3({ buffer, contentType, folder = 'uploads', fileName, origin }) {
  const bucket = getBucket();
  const ext = EXT_BY_TYPE[contentType] || 'bin';
  const safeName = (fileName || randomUUID()).replace(/[^\w.-]/g, '_');
  const key = `${folder.replace(/^\/|\/$/g, '')}/${Date.now()}-${safeName}.${ext}`;

  if (!isPublicAssetKey(key)) {
    throw new Error('Upload folder must be under party-symbols/ or candidates/.');
  }

  await getS3Client().send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: buffer,
      ContentType: contentType,
      ContentDisposition: 'inline',
      CacheControl: 'public, max-age=31536000, immutable',
    }),
  );

  return { key, url: buildAssetProxyUrl(key, origin) };
}

/** Derive request origin for absolute proxy URLs (upload responses, on-chain). */
export function getRequestOrigin(req) {
  const host = req.headers.get('x-forwarded-host') || req.headers.get('host');
  const proto = req.headers.get('x-forwarded-proto') || 'http';
  if (host) return `${proto}://${host}`;
  return (process.env.NEXTAUTH_URL || '').replace(/\/$/, '');
}

/** Shared URL helpers (safe for client and server). */

export const PUBLIC_ASSET_PREFIXES = ['party-symbols/', 'candidates/'];

export function isHttpUrl(value) {
  return typeof value === 'string' && /^https?:\/\//i.test(value.trim());
}

export function isPublicAssetKey(key) {
  if (!key || typeof key !== 'string') return false;
  const normalized = key.replace(/^\/+/, '');
  return PUBLIC_ASSET_PREFIXES.some((prefix) => normalized.startsWith(prefix));
}

/** Build a same-origin proxy path for an S3 object key. */
export function buildAssetProxyPath(key) {
  const normalized = key.replace(/^\/+/, '');
  const encoded = normalized.split('/').map(encodeURIComponent).join('/');
  return `/api/assets/${encoded}`;
}

/**
 * Extract the S3 object key from a virtual-hosted–style S3 URL, or null.
 * Handles regional endpoints and URL-encoded path segments.
 */
export function extractS3KeyFromUrl(url) {
  if (!isHttpUrl(url)) return null;
  try {
    const { hostname, pathname } = new URL(url.trim());
    if (!/\.s3(\.[a-z0-9-]+)?\.amazonaws\.com$/i.test(hostname)) return null;
    const key = decodeURIComponent(pathname.replace(/^\/+/, ''));
    return key || null;
  } catch {
    return null;
  }
}

/**
 * Resolve a stored symbol/photo URL for display.
 * Rewrites direct S3 URLs to the authenticated proxy; leaves proxy URLs unchanged.
 */
export function resolveAssetUrl(value, baseOrigin) {
  if (!value || typeof value !== 'string') return '';
  const trimmed = value.trim();
  if (!trimmed) return '';

  if (trimmed.startsWith('/api/assets/')) {
    const origin = (baseOrigin || '').replace(/\/$/, '');
    return origin ? `${origin}${trimmed}` : trimmed;
  }

  if (/^https?:\/\/[^/]+\/api\/assets\//i.test(trimmed)) {
    return trimmed;
  }

  const s3Key = extractS3KeyFromUrl(trimmed);
  if (s3Key && isPublicAssetKey(s3Key)) {
    const proxyPath = buildAssetProxyPath(s3Key);
    const origin = (baseOrigin || '').replace(/\/$/, '');
    if (origin) return `${origin}${proxyPath}`;
    if (typeof window !== 'undefined') return proxyPath;
    return proxyPath;
  }

  return trimmed;
}

/** Accept proxy paths and HTTP(S) URLs for on-chain / API validation. */
export function isAllowedAssetUrl(value) {
  if (!value || typeof value !== 'string') return false;
  const trimmed = value.trim();
  if (trimmed.startsWith('/api/assets/')) return isPublicAssetKey(trimmed.slice('/api/assets/'.length));
  if (!isHttpUrl(trimmed)) return false;
  if (trimmed.includes('/api/assets/')) {
    try {
      const key = decodeURIComponent(new URL(trimmed).pathname.replace(/^\/api\/assets\/?/, ''));
      return isPublicAssetKey(key);
    } catch {
      return false;
    }
  }
  const s3Key = extractS3KeyFromUrl(trimmed);
  if (s3Key && isPublicAssetKey(s3Key)) return true;
  return isHttpUrl(trimmed);
}

import { ethers } from 'ethers';

/**
 * Canonical on-chain voter identity (email-scoped, no organization).
 * Same email → same nullifier across elections (biometric + double-vote binding).
 */
export function computeNullifierHash(email) {
  const secret = process.env.SERVER_IDENTITY_SECRET || 'dev-identity-secret-change-in-prod-12345';
  const cleanEmail = email.toLowerCase().trim();
  return ethers.keccak256(
    ethers.toUtf8Bytes(`${cleanEmail}:${secret}`),
  );
}

export function isAlreadyRegisteredError(err) {
  const msg = err?.reason || err?.message || String(err);
  return msg.includes('already registered');
}

